export type KernelVec2 = [number, number];
export type KernelVec3 = [number, number, number];

export interface KernelBodyLike {
  shape: string;
  size: KernelVec3;
  sides?: number;
  profile?: KernelVec2[];
  profileHoles?: KernelVec2[][];
  mesh?: { vertices: number[]; indices: number[]; diagnostics?: { volume: number } };
  revolve?: { angle: number };
}

export interface KernelValidationIssue {
  code:
    | "INVALID_DIMENSIONS"
    | "INVALID_SEGMENTS"
    | "INVALID_PROFILE"
    | "SELF_INTERSECTING_TORUS"
    | "UNSUPPORTED_SHAPE";
  message: string;
  suggestion: string;
}

const SUPPORTED_SHAPES = new Set([
  "Box",
  "Cylinder",
  "Sphere",
  "Cone",
  "Torus",
  "Wedge",
  "Pyramid",
  "Tube",
  "Rounded box",
  "Polygon prism",
  "Text",
  "Extrusion",
  "Revolution",
  "Sweep",
  "Loft",
  "Imported mesh",
]);

export function kernelSegments(body: KernelBodyLike) {
  if (body.shape === "Polygon prism") return body.sides ?? 6;
  if (body.shape === "Pyramid") return 4;
  if (body.shape === "Cylinder" || body.shape === "Cone")
    return body.sides ?? 48;
  if (body.shape === "Tube") return body.sides ?? 48;
  return 48;
}

export function torusParameters(size: KernelVec3) {
  const tubeRadius = size[2] / 2;
  return {
    tubeRadius,
    majorRadius: size[0] / 2 - tubeRadius,
    radialSegments: 24,
    tubularSegments: 64,
  };
}

export function tubeParameters(size: KernelVec3) {
  return {
    outerRadius: size[0] / 2,
    innerRadius: Math.min(size[0], size[1]) * 0.28,
  };
}

export function roundedBoxParameters(size: KernelVec3) {
  return {
    radius: Math.min(...size) * 0.12,
    cornerSegments: 18,
  };
}

export function validateKernelBody(
  body: KernelBodyLike,
): KernelValidationIssue | null {
  if (!SUPPORTED_SHAPES.has(body.shape))
    return {
      code: "UNSUPPORTED_SHAPE",
      message: `${body.shape} has no solid-kernel implementation.`,
      suggestion: "Suppress this feature or replace it with a supported solid.",
    };
  if (
    body.size.length !== 3 ||
    body.size.some((value) => !Number.isFinite(value) || value <= 0)
  )
    return {
      code: "INVALID_DIMENSIONS",
      message: `${body.shape} dimensions must be finite and greater than zero.`,
      suggestion: "Edit Width, Depth, and Height in the Inspector.",
    };
  if (
    ["Cylinder", "Cone", "Tube", "Polygon prism"].includes(body.shape) &&
    (!Number.isInteger(kernelSegments(body)) ||
      kernelSegments(body) < 3 ||
      kernelSegments(body) > 256)
  )
    return {
      code: "INVALID_SEGMENTS",
      message: `${body.shape} requires between 3 and 256 whole-number sides.`,
      suggestion: "Set Sides to a whole number from 3 through 256.",
    };
  if (body.shape === "Extrusion" && (!body.profile || body.profile.length < 3))
    return {
      code: "INVALID_PROFILE",
      message: "Extrusion profile is open or missing.",
      suggestion: "Repair or reselect a closed sketch profile.",
    };
  if (body.shape === "Revolution" && (!body.profile || body.profile.length < 3))
    return {
      code: "INVALID_PROFILE",
      message: "Revolve profile is open or missing.",
      suggestion: "Repair or reselect a closed sketch profile.",
    };
  if (body.shape === "Sweep" && (!body.profile || body.profile.length < 3))
    return {
      code: "INVALID_PROFILE",
      message: "Sweep profile is open or missing.",
      suggestion: "Repair or reselect a closed sketch profile.",
    };
  if (body.shape === "Revolution" && (!body.revolve || body.revolve.angle <= 0 || body.revolve.angle > 360))
    return {
      code: "INVALID_DIMENSIONS",
      message: "Revolve angle must be greater than 0° and no more than 360°.",
      suggestion: "Edit Angle in the Revolve inspector.",
    };
  if (body.shape === "Imported mesh" && (!body.mesh || body.mesh.indices.length < 3))
    return {
      code: "INVALID_PROFILE",
      message: "Imported mesh triangles are missing.",
      suggestion: "Reimport the source geometry.",
    };
  if (body.shape === "Torus") {
    const { majorRadius, tubeRadius } = torusParameters(body.size);
    if (majorRadius <= tubeRadius)
      return {
        code: "SELF_INTERSECTING_TORUS",
        message: "Torus tube diameter is too large for its outside diameter.",
        suggestion: "Increase Width or reduce Height until Width is greater than twice Height.",
      };
  }
  return null;
}

function polygonArea(points: KernelVec2[]) {
  return Math.abs(
    points.reduce((area, point, index) => {
      const next = points[(index + 1) % points.length];
      return area + point[0] * next[1] - next[0] * point[1];
    }, 0) / 2,
  );
}

function polygonAreaCentroidX(points: KernelVec2[]) {
  let twiceArea = 0;
  let xMoment = 0;
  points.forEach((point, index) => {
    const next = points[(index + 1) % points.length];
    const cross = point[0] * next[1] - next[0] * point[1];
    twiceArea += cross;
    xMoment += (point[0] + next[0]) * cross;
  });
  const area = Math.abs(twiceArea / 2);
  return { area, centroidX: Math.abs(twiceArea) < 1e-12 ? 0 : Math.abs(xMoment / (3 * twiceArea)) };
}

function regularPolygonArea(radius: number, sides: number) {
  return (sides * radius * radius * Math.sin((Math.PI * 2) / sides)) / 2;
}

export function expectedPrimitiveVolume(body: KernelBodyLike) {
  const validation = validateKernelBody(body);
  if (validation) return null;
  const [x, y, z] = body.size;
  switch (body.shape) {
    case "Box":
    case "Text":
      return x * y * z;
    case "Cylinder":
    case "Polygon prism": {
      const sides = kernelSegments(body);
      const bottomArea = regularPolygonArea(y / 2, sides);
      const topArea = regularPolygonArea(x / 2, sides);
      return (z / 3) * (bottomArea + Math.sqrt(bottomArea * topArea) + topArea);
    }
    case "Sphere":
      return (4 * Math.PI * (x / 2) ** 3) / 3;
    case "Cone":
    case "Pyramid":
      return (regularPolygonArea(x / 2, kernelSegments(body)) * z) / 3;
    case "Torus": {
      const { majorRadius, tubeRadius } = torusParameters(body.size);
      return 2 * Math.PI ** 2 * majorRadius * tubeRadius ** 2;
    }
    case "Tube": {
      const { outerRadius, innerRadius } = tubeParameters(body.size);
      return Math.PI * (outerRadius ** 2 - innerRadius ** 2) * z;
    }
    case "Rounded box": {
      const { radius } = roundedBoxParameters(body.size);
      return (x * y - (4 - Math.PI) * radius ** 2) * z;
    }
    case "Wedge":
      return (x * y * z) / 2;
    case "Extrusion":
      return (
        (polygonArea(body.profile!) -
          (body.profileHoles ?? []).reduce(
            (area, hole) => area + polygonArea(hole),
            0,
          )) * z
      );
    case "Revolution": {
      const outer = polygonAreaCentroidX(body.profile!);
      const holeMoment = (body.profileHoles ?? []).reduce((sum, hole) => {
        const value = polygonAreaCentroidX(hole);
        return sum + value.area * value.centroidX;
      }, 0);
      const sweep = (body.revolve?.angle ?? 360) * Math.PI / 180;
      return sweep * Math.max(0, outer.area * outer.centroidX - holeMoment);
    }
    case "Imported mesh":
      return body.mesh?.diagnostics?.volume ?? null;
    default:
      return null;
  }
}
