export type SelectionBehavior = "replace" | "add" | "remove" | "toggle";

export function applySelectionBehavior(
  current: string[],
  incoming: string[],
  behavior: SelectionBehavior,
) {
  if (behavior === "replace") return [...new Set(incoming)];
  if (behavior === "add") return [...new Set([...current, ...incoming])];
  if (behavior === "remove")
    return current.filter((id) => !incoming.includes(id));
  const toggled = new Set(current);
  incoming.forEach((id) =>
    toggled.has(id) ? toggled.delete(id) : toggled.add(id),
  );
  return [...toggled];
}
