import JSZip from "jszip";

import {
  APP_VERSION,
  SCHEMA_VERSION,
  migrateProject,
  type BenchProject,
  type Workplane,
} from "@/lib/benchcad-model";
import { base64ToUint8Array } from "@/lib/benchcad-mesh";

export const INTEGRITY_ALGORITHM = "SHA-256" as const;

type ArchiveValue = string | Uint8Array;

export interface ProjectArchiveResult {
  blob: Blob;
  projectHash: string;
}

export interface OpenedProjectArchive {
  project: BenchProject;
  integrityVerified: boolean;
  projectHash: string;
}

interface IntegrityManifest {
  algorithm: typeof INTEGRITY_ALGORITHM;
  files: Record<string, string>;
}

function bytesFor(value: ArchiveValue) {
  return typeof value === "string" ? new TextEncoder().encode(value) : value;
}

export async function sha256Hex(value: ArchiveValue | ArrayBuffer) {
  if (!globalThis.crypto?.subtle)
    throw new Error("SHA-256 verification is unavailable in this browser");
  const bytes = value instanceof ArrayBuffer ? new Uint8Array(value) : bytesFor(value);
  const digestInput = new ArrayBuffer(bytes.byteLength);
  new Uint8Array(digestInput).set(bytes);
  const digest = await globalThis.crypto.subtle.digest("SHA-256", digestInput);
  return [...new Uint8Array(digest)]
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

async function hashEntries(entries: Record<string, ArchiveValue>) {
  const pairs = await Promise.all(
    Object.entries(entries).map(async ([path, value]) => [path, await sha256Hex(value)] as const),
  );
  return Object.fromEntries(pairs);
}

function projectAssetEntries(project: BenchProject) {
  const bodies = project.features
    .flatMap((feature) => [
      ...(feature.snapshot ? [feature.snapshot] : []),
      ...(feature.bodySnapshots ?? []),
    ])
    .filter(
      (body, index, all) =>
        Boolean(body.mesh?.sourceData) &&
        all.findIndex((candidate) => candidate.id === body.id) === index,
    );
  const assets = bodies.map((body) => {
    const filename = body.mesh!.sourceName.replace(/[^a-z0-9._-]+/gi, "-");
    const path = `assets/${body.id}-${filename}`;
    return {
      bodyId: body.id,
      filename: body.mesh!.sourceName,
      path,
      format: body.mesh!.sourceFormat,
      bytes: body.mesh!.sourceFileSize,
      data: base64ToUint8Array(body.mesh!.sourceData!),
    };
  });
  return {
    entries: Object.fromEntries(assets.map((asset) => [asset.path, asset.data])),
    assets,
  };
}

export async function createProjectArchive(
  project: BenchProject,
  workplanes: Workplane[] = [],
): Promise<ProjectArchiveResult> {
  const projectAssets = projectAssetEntries(project);
  const entries: Record<string, ArchiveValue> = {
    "project.json": JSON.stringify(project, null, 2),
    "components.json": JSON.stringify(project.components, null, 2),
    "occurrences.json": JSON.stringify(project.occurrences, null, 2),
    "joints.json": JSON.stringify(project.joints, null, 2),
    "workplanes.json": JSON.stringify(workplanes, null, 2),
    "history.json": JSON.stringify(project.features, null, 2),
    "checkpoints.json": JSON.stringify(project.checkpoints, null, 2),
    "drawings.json": JSON.stringify(project.drawings, null, 2),
    ...projectAssets.entries,
    "README.txt":
      "This is a local BENCHCAD project archive. Open it with BENCHCAD; no server or account is required.",
  };
  const hashes = await hashEntries(entries);
  const assets = projectAssets.assets.map((asset) => ({
    bodyId: asset.bodyId,
    filename: asset.filename,
    path: asset.path,
    format: asset.format,
    bytes: asset.bytes,
    sha256: hashes[asset.path],
  }));
  const manifest = {
    format: "BENCHCAD",
    schemaVersion: project.schemaVersion,
    appVersion: APP_VERSION,
    projectId: project.id,
    exportedAt: new Date().toISOString(),
    integrity: {
      algorithm: INTEGRITY_ALGORITHM,
      files: hashes,
    } satisfies IntegrityManifest,
    assets,
  };
  const zip = new JSZip();
  Object.entries(entries).forEach(([path, value]) => zip.file(path, value));
  zip.file("manifest.json", JSON.stringify(manifest, null, 2));
  return {
    blob: await zip.generateAsync({ type: "blob", compression: "DEFLATE" }),
    projectHash: hashes["project.json"],
  };
}

async function verifyZipIntegrity(zip: JSZip, integrity: IntegrityManifest) {
  if (integrity.algorithm !== INTEGRITY_ALGORITHM)
    throw new Error(`Unsupported archive integrity algorithm: ${integrity.algorithm}`);
  for (const [path, expected] of Object.entries(integrity.files)) {
    const entry = zip.file(path);
    if (!entry) throw new Error(`Archive integrity failed: ${path} is missing`);
    const actual = await sha256Hex(await entry.async("uint8array"));
    if (actual !== expected)
      throw new Error(`Archive integrity failed: ${path} does not match its SHA-256 hash`);
  }
}

export async function openProjectArchive(source: ArrayBuffer | Blob): Promise<OpenedProjectArchive> {
  const zip = await JSZip.loadAsync(source);
  const manifestText = await zip.file("manifest.json")?.async("text");
  const projectText = await zip.file("project.json")?.async("text");
  if (!projectText) throw new Error("This archive does not contain project.json");
  const manifest = manifestText ? JSON.parse(manifestText) : null;
  if (manifest && manifest.format !== "BENCHCAD")
    throw new Error("This ZIP is not a BENCHCAD project archive");
  const integrity = manifest?.integrity as IntegrityManifest | undefined;
  if (integrity) await verifyZipIntegrity(zip, integrity);
  const projectHash = await sha256Hex(projectText);
  return {
    project: migrateProject(JSON.parse(projectText)),
    integrityVerified: Boolean(integrity),
    projectHash,
  };
}

export async function createRecoveryArchive(projects: BenchProject[]) {
  const unique = [...new Map(projects.map((project) => [project.id, project])).values()];
  const entries: Record<string, string> = Object.fromEntries(
    unique.map((project) => [`projects/${project.id}.json`, JSON.stringify(project, null, 2)]),
  );
  const hashes = await hashEntries(entries);
  const manifest = {
    format: "BENCHCAD-RECOVERY",
    appVersion: APP_VERSION,
    schemaVersion: SCHEMA_VERSION,
    exportedAt: new Date().toISOString(),
    projectCount: unique.length,
    integrity: {
      algorithm: INTEGRITY_ALGORITHM,
      files: hashes,
    } satisfies IntegrityManifest,
  };
  const zip = new JSZip();
  Object.entries(entries).forEach(([path, value]) => zip.file(path, value));
  zip.file("manifest.json", JSON.stringify(manifest, null, 2));
  zip.file(
    "README.txt",
    "BENCHCAD local project library recovery backup. Import this file from Recovery & Storage Health.",
  );
  return zip.generateAsync({ type: "blob", compression: "DEFLATE" });
}

export async function openRecoveryArchive(source: ArrayBuffer | Blob) {
  const zip = await JSZip.loadAsync(source);
  const manifestText = await zip.file("manifest.json")?.async("text");
  if (!manifestText) throw new Error("Recovery manifest is missing");
  const manifest = JSON.parse(manifestText);
  if (manifest.format !== "BENCHCAD-RECOVERY")
    throw new Error("This file is not a BENCHCAD recovery backup");
  const integrity = manifest.integrity as IntegrityManifest | undefined;
  if (!integrity) throw new Error("Recovery backup has no integrity record");
  await verifyZipIntegrity(zip, integrity);
  return Promise.all(
    Object.keys(integrity.files)
      .filter((path) => path.startsWith("projects/") && path.endsWith(".json"))
      .map(async (path) => migrateProject(JSON.parse(await zip.file(path)!.async("text")))),
  );
}
