export interface CapabilityCheck {
  id: string;
  label: string;
  available: boolean;
  required: boolean;
  detail: string;
}

export interface RuntimeCapabilitySource {
  protocol: string;
  indexedDB: boolean;
  workers: boolean;
  webAssembly: boolean;
  crypto: boolean;
  serviceWorker: boolean;
}

export function runtimeCapabilityChecks(source: RuntimeCapabilitySource): CapabilityCheck[] {
  const hosted = source.protocol === "https:" || source.protocol === "http:";
  return [
    {
      id: "protocol",
      label: "Hosted application",
      available: hosted,
      required: true,
      detail: hosted
        ? "HTTP(S) permits workers, storage, and offline caching"
        : "Open through a local or remote web server; file:// restricts CAD workers",
    },
    {
      id: "indexeddb",
      label: "Local project storage",
      available: source.indexedDB,
      required: true,
      detail: source.indexedDB ? "IndexedDB is available" : "Autosave is unavailable",
    },
    {
      id: "workers",
      label: "Geometry workers",
      available: source.workers,
      required: true,
      detail: source.workers ? "Background geometry processing is available" : "Model rebuilds cannot run",
    },
    {
      id: "wasm",
      label: "Manifold engine",
      available: source.webAssembly,
      required: true,
      detail: source.webAssembly ? "WebAssembly is available" : "Exact solid operations cannot run",
    },
    {
      id: "crypto",
      label: "Archive verification",
      available: source.crypto,
      required: true,
      detail: source.crypto ? "SHA-256 verification is available" : "Archive integrity cannot be verified",
    },
    {
      id: "service-worker",
      label: "Offline application shell",
      available: hosted && source.serviceWorker,
      required: false,
      detail: hosted && source.serviceWorker ? "Offline caching is supported" : "Service workers require HTTP(S)",
    },
  ];
}

export function formatBytes(value: number | null) {
  if (value === null || !Number.isFinite(value)) return "Unavailable";
  if (value < 1024) return `${value} B`;
  const units = ["KB", "MB", "GB", "TB"];
  let size = value / 1024;
  let index = 0;
  while (size >= 1024 && index < units.length - 1) {
    size /= 1024;
    index += 1;
  }
  return `${size.toFixed(size >= 10 ? 1 : 2)} ${units[index]}`;
}

export function serviceWorkerAllowed(protocol: string) {
  return protocol === "https:" || protocol === "http:";
}
