export function planeForFace(face: BodyFace): SketchPlane {
  if (face === "top" || face === "bottom") return "XY";
  if (face === "front" || face === "back") return "XZ";
  return "YZ";
}

export function normalForFace(face: BodyFace): -1 | 1 {
  return face === "bottom" || face === "front" || face === "left" ? -1 : 1;
}

export function makeWorkplane(
  name = "Workplane 1",
  plane: SketchPlane = "XY",
  componentId = "",
  overrides: Partial<Workplane> = {},
): Workplane {
  const now = new Date().toISOString();
  return {
    id: uid("workplane"),
    componentId,
    name,
    plane,
    origin: [0, 0, 10],
    normal: 1,
    visible: true,
    createdAt: now,
    updatedAt: now,
    ...overrides,
  };
}

const frameRadians = (degrees: number) => degrees * Math.PI / 180;
const frameDot = (first: Vec3, second: Vec3) =>
  first[0] * second[0] + first[1] * second[1] + first[2] * second[2];
const frameCross = (first: Vec3, second: Vec3): Vec3 => [
  first[1] * second[2] - first[2] * second[1],
  first[2] * second[0] - first[0] * second[2],
  first[0] * second[1] - first[1] * second[0],
];
const frameLength = (value: Vec3) => Math.hypot(...value);
const frameNormalize = (value: Vec3): Vec3 => {
  const length = frameLength(value);
  if (length <= 1e-12) throw new Error("A planar reference axis has zero length.");
  return value.map((entry) => entry / length) as Vec3;
};

function rotateFrameX([x, y, z]: Vec3, angle: number): Vec3 {
  const cosine = Math.cos(angle), sine = Math.sin(angle);
  return [x, y * cosine - z * sine, y * sine + z * cosine];
}

function rotateFrameY([x, y, z]: Vec3, angle: number): Vec3 {
  const cosine = Math.cos(angle), sine = Math.sin(angle);
  return [x * cosine + z * sine, y, -x * sine + z * cosine];
}

function rotateFrameZ([x, y, z]: Vec3, angle: number): Vec3 {
  const cosine = Math.cos(angle), sine = Math.sin(angle);
  return [x * cosine - y * sine, x * sine + y * cosine, z];
}

export function rotateBodyVector(body: Pick<Body, "rotation">, vector: Vec3): Vec3 {
  let result = rotateFrameX(vector, frameRadians(body.rotation[0]));
  result = rotateFrameY(result, frameRadians(body.rotation[1]));
  return rotateFrameZ(result, frameRadians(body.rotation[2]));
}

export function inverseRotateBodyVector(body: Pick<Body, "rotation">, vector: Vec3): Vec3 {
  let result = rotateFrameZ(vector, frameRadians(-body.rotation[2]));
  result = rotateFrameY(result, frameRadians(-body.rotation[1]));
  return rotateFrameX(result, frameRadians(-body.rotation[0]));
}

function applyBodyOrientation(
  body: Pick<Body, "orientation">,
  vector: Vec3,
): Vec3 {
  if (!body.orientation) return [...vector];
  return [0, 1, 2].map(
    (axis) =>
      body.orientation!.xAxis[axis] * vector[0] +
      body.orientation!.yAxis[axis] * vector[1] +
      body.orientation!.normal[axis] * vector[2],
  ) as Vec3;
}

function removeBodyOrientation(
  body: Pick<Body, "orientation">,
  vector: Vec3,
): Vec3 {
  if (!body.orientation) return [...vector];
  return [
    frameDot(vector, body.orientation.xAxis),
    frameDot(vector, body.orientation.yAxis),
    frameDot(vector, body.orientation.normal),
  ];
}

export function bodyPointToLocal(body: Body, point: Vec3): Vec3 {
  const translated = point.map((value, axis) => value - body.position[axis]) as Vec3;
  const rotated = inverseRotateBodyVector(body, translated);
  const oriented = removeBodyOrientation(body, rotated);
  return oriented.map(
    (value, axis) => value / (body.mirrorAxes?.[axis] ?? 1),
  ) as Vec3;
}

function bodyLocalPointToWorld(body: Body, point: Vec3): Vec3 {
  const transformed = bodyLocalDirectionToWorld(body, point);
  return transformed.map((value, axis) => value + body.position[axis]) as Vec3;
}

function bodyLocalDirectionToWorld(body: Body, vector: Vec3): Vec3 {
  const mirrored = vector.map(
    (value, axis) => value * (body.mirrorAxes?.[axis] ?? 1),
  ) as Vec3;
  const oriented = applyBodyOrientation(body, mirrored);
  return rotateBodyVector(body, oriented);
}

export function axisAlignedWorkplaneFrame(workplane: Pick<Workplane, "plane" | "origin" | "normal">): PlaneFrame {
  if (workplane.plane === "XY")
    return {
      origin: [...workplane.origin],
      xAxis: [1, 0, 0],
      yAxis: [0, workplane.normal, 0],
      normal: [0, 0, workplane.normal],
    };
  if (workplane.plane === "XZ")
    return {
      origin: [...workplane.origin],
      xAxis: [1, 0, 0],
      yAxis: [0, 0, 1],
      normal: [0, workplane.normal, 0],
    };
  return {
    origin: [...workplane.origin],
    xAxis: [0, 1, 0],
    yAxis: [0, 0, 1],
    normal: [workplane.normal, 0, 0],
  };
}

export function workplaneFrame(workplane: Workplane): PlaneFrame {
  return workplane.frame
    ? structuredClone(workplane.frame)
    : axisAlignedWorkplaneFrame(workplane);
}

export function workplaneReferenceIssue(
  workplane: Workplane,
  bodies: Body[],
): string | null {
  const bodyId =
    workplane.faceReference?.bodyId ?? workplane.attachment?.bodyId;
  if (!bodyId) return null;
  const body = bodies.find((item) => item.id === bodyId);
  if (!body)
    return "is unresolved because its reference body is unavailable.";
  if (
    workplane.faceReference &&
    body.shape !== workplane.faceReference.sourceShape
  )
    return "is using its last valid frame because the referenced face topology changed.";
  return null;
}

export function makePlanarFaceReference(
  body: Body,
  face: {
    id: string;
    planar: boolean;
    centroid: Vec3;
    normal: Vec3 | null;
    points: Vec3[];
  },
): PlanarFaceReference {
  if (!face.planar || !face.normal)
    throw new Error("Choose one planar face to create an oriented workplane.");
  if (face.points.length < 3)
    throw new Error("The selected face does not provide a stable planar frame.");
  const localPoints = face.points.map((point) => bodyPointToLocal(body, point));
  const normalizedPoints = localPoints.map((point) =>
    point.map(
      (value, axis) => value / Math.max(0.000001, body.size[axis]),
    ) as Vec3,
  );
  const localOrigin = bodyPointToLocal(body, face.centroid);
  let longestLength = 0;
  for (let first = 0; first < normalizedPoints.length; first += 1) {
    for (let second = first + 1; second < normalizedPoints.length; second += 1) {
      const delta = normalizedPoints[second].map(
        (value, axis) => value - normalizedPoints[first][axis],
      ) as Vec3;
      const length = frameLength(delta);
      if (length > longestLength) longestLength = length;
    }
  }
  if (longestLength <= 1e-8)
    throw new Error("The selected face is too small to define a workplane.");
  const inverseNormal = removeBodyOrientation(
    body,
    inverseRotateBodyVector(body, face.normal),
  ).map(
    (value, axis) => value * (body.mirrorAxes?.[axis] ?? 1),
  ) as Vec3;
  const localNormal = frameNormalize(
    inverseNormal.map(
      (value, axis) => value * Math.max(0.000001, body.size[axis]),
    ) as Vec3,
  );
  const localXAxis = ([
    [1, 0, 0],
    [0, 1, 0],
    [0, 0, 1],
  ] as Vec3[])
    .map((candidate, index) => {
      const projected = candidate.map(
        (value, axis) =>
          value - localNormal[axis] * frameDot(candidate, localNormal),
      ) as Vec3;
      return { index, projected, length: frameLength(projected) };
    })
    .sort(
      (first, second) =>
        second.length - first.length || first.index - second.index,
    )[0].projected;
  const normalizedXAxis = frameNormalize(localXAxis);
  const localYAxis = frameNormalize(frameCross(localNormal, normalizedXAxis));
  return {
    bodyId: body.id,
    topologyId: face.id,
    sourceShape: body.shape,
    normalizedOrigin: localOrigin.map(
      (value, axis) => value / Math.max(0.000001, body.size[axis]),
    ) as Vec3,
    localXAxis: normalizedXAxis,
    localYAxis,
    localNormal,
  };
}

function resolvePlanarFaceFrame(
  body: Body,
  reference: PlanarFaceReference,
  offset: number,
  flipped: boolean,
): PlaneFrame {
  if (body.shape !== reference.sourceShape)
    throw new Error("The referenced body no longer has the original face topology.");
  const localOrigin = reference.normalizedOrigin.map(
    (value, axis) => value * body.size[axis],
  ) as Vec3;
  const transformTangent = (axis: Vec3) =>
    rotateBodyVector(
      body,
      applyBodyOrientation(body, axis.map(
        (value, index) =>
          value * body.size[index] * (body.mirrorAxes?.[index] ?? 1),
      ) as Vec3),
    );
  const transformedX = frameNormalize(transformTangent(reference.localXAxis));
  const transformedY = frameNormalize(transformTangent(reference.localYAxis));
  const expectedNormal = frameNormalize(
    rotateBodyVector(
      body,
      applyBodyOrientation(body, reference.localNormal.map(
        (value, axis) =>
          value * (body.mirrorAxes?.[axis] ?? 1) /
          Math.max(0.000001, body.size[axis]),
      ) as Vec3),
    ),
  );
  let normal = frameNormalize(frameCross(transformedX, transformedY));
  if (frameDot(normal, expectedNormal) < 0)
    normal = normal.map((value) => -value) as Vec3;
  let xAxis = transformedX.map(
    (value, axis) => value - normal[axis] * frameDot(transformedX, normal),
  ) as Vec3;
  xAxis = frameNormalize(xAxis);
  let yAxis = frameNormalize(frameCross(normal, xAxis));
  if (flipped) {
    normal = normal.map((value) => -value) as Vec3;
    yAxis = yAxis.map((value) => -value) as Vec3;
  }
  const baseOrigin = bodyLocalPointToWorld(body, localOrigin);
  const origin = baseOrigin.map(
    (value, axis) => value + normal[axis] * offset,
  ) as Vec3;
  return { origin, xAxis, yAxis, normal };
}

export function resolveWorkplane(
  workplane: Workplane,
  bodies: Body[],
): Workplane {
  if (workplane.faceReference) {
    const body = bodies.find(
      (item) => item.id === workplane.faceReference?.bodyId,
    );
    if (
      !body ||
      body.shape !== workplane.faceReference.sourceShape
    )
      return structuredClone(workplane);
    try {
      const frame = resolvePlanarFaceFrame(
        body,
        workplane.faceReference,
        workplane.offset ?? 0,
        Boolean(workplane.flipped),
      );
      const dominant = frame.normal
        .map((value, axis) => ({ axis, value: Math.abs(value) }))
        .sort((first, second) => second.value - first.value)[0].axis;
      return {
        ...structuredClone(workplane),
        plane: dominant === 2 ? "XY" : dominant === 1 ? "XZ" : "YZ",
        origin: frame.origin,
        normal: frame.normal[dominant] < 0 ? -1 : 1,
        frame,
      };
    } catch {
      return structuredClone(workplane);
    }
  }
  if (!workplane.attachment) return structuredClone(workplane);
  const body = bodies.find((item) => item.id === workplane.attachment?.bodyId);
  if (!body) return structuredClone(workplane);
  const { face, offset } = workplane.attachment;
  const origin = [...body.position] as Vec3;
  const axis: Axis3 = planeForFace(face) === "XY" ? 2 : planeForFace(face) === "XZ" ? 1 : 0;
  origin[axis] += normalForFace(face) * (body.size[axis] / 2 + offset);
  return {
    ...structuredClone(workplane),
    plane: planeForFace(face),
    normal: normalForFace(face),
    origin,
  };
}

export function workplaneNormalVector(workplane: Workplane): Vec3 {
  if (workplane.frame) return [...workplane.frame.normal];
  if (workplane.plane === "XY") return [0, 0, workplane.normal];
  if (workplane.plane === "XZ") return [0, workplane.normal, 0];
  return [workplane.normal, 0, 0];
}

export function workplaneCoordinates(point: Vec3, workplane: Workplane): Vec3 {
  const frame = workplane.frame ? workplaneFrame(workplane) : null;
  const origin = frame?.origin ?? workplane.origin;
  const delta = point.map((value, axis) => value - origin[axis]) as Vec3;
  if (frame)
    return [
      frameDot(delta, frame.xAxis),
      frameDot(delta, frame.yAxis),
      frameDot(delta, frame.normal),
    ];
  if (workplane.plane === "XY")
    return [delta[0], delta[1], delta[2] * workplane.normal];
  if (workplane.plane === "XZ")
    return [delta[0], delta[2], delta[1] * workplane.normal];
  return [delta[1], delta[2], delta[0] * workplane.normal];
}

export function placeBodyOnWorkplane(
  body: Body,
  workplane: Workplane,
  local: Vec2 = [0, 0],
): Body {
  const next = structuredClone(body);
  const halfHeight = next.size[2] / 2;
  if (workplane.frame) {
    const frame = workplaneFrame(workplane);
    next.position = frame.origin.map(
      (value, axis) =>
        value +
        frame.xAxis[axis] * local[0] +
        frame.yAxis[axis] * local[1] +
        frame.normal[axis] * halfHeight,
    ) as Vec3;
    next.rotation = [0, 0, 0];
    next.orientation = {
      xAxis: frame.xAxis,
      yAxis: frame.yAxis,
      normal: frame.normal,
    };
    return next;
  }
  if (workplane.plane === "XY") {
    next.position = [
      workplane.origin[0] + local[0],
      workplane.origin[1] + local[1],
      workplane.origin[2] + workplane.normal * halfHeight,
    ];
    next.rotation = workplane.normal === 1 ? [0, 0, 0] : [180, 0, 0];
  } else if (workplane.plane === "XZ") {
    next.position = [
      workplane.origin[0] + local[0],
      workplane.origin[1] + workplane.normal * halfHeight,
      workplane.origin[2] + local[1],
    ];
    next.rotation = workplane.normal === 1 ? [-90, 0, 0] : [90, 0, 0];
  } else {
    next.position = [
      workplane.origin[0] + workplane.normal * halfHeight,
      workplane.origin[1] + local[0],
      workplane.origin[2] + local[1],
    ];
    next.rotation = workplane.normal === 1 ? [0, 90, 0] : [0, -90, 0];
  }
  return next;
}

export interface BodyMeasurement {
  delta: Vec3;
  centerDistance: number;
  axisSeparation: Vec3;
  clearance: number;
}

export function measureBodies(first: Body, second: Body): BodyMeasurement {
  const delta = second.position.map(
    (value, axis) => Number((value - first.position[axis]).toFixed(4)),
  ) as Vec3;
  const axisSeparation = delta.map((value, axis) =>
    Number((Math.abs(value) - (first.size[axis] + second.size[axis]) / 2).toFixed(4)),
  ) as Vec3;
  return {
    delta,
    centerDistance: Number(Math.hypot(...delta).toFixed(4)),
    axisSeparation,
    clearance: Number(
      Math.hypot(...axisSeparation.map((value) => Math.max(0, value))).toFixed(4),
    ),
  };
}

function planeFootprint(body: Body, plane: SketchPlane) {
  if (plane === "XZ")
    return {
      center: [body.position[0], body.position[2]] as Vec2,
      width: body.size[0],
      height: body.size[2],
    };
  if (plane === "YZ")
    return {
      center: [body.position[1], body.position[2]] as Vec2,
      width: body.size[1],
      height: body.size[2],
    };
  return {
    center: [body.position[0], body.position[1]] as Vec2,
    width: body.size[0],
    height: body.size[1],
  };
}

function convexProjectionHull(points: Vec2[]): Vec2[] {
  const unique = new Map(
    points.map((point) => [
      `${point[0].toFixed(8)}:${point[1].toFixed(8)}`,
      point,
    ]),
  );
  const sorted = [...unique.values()].sort(
    (first, second) => first[0] - second[0] || first[1] - second[1],
  );
  if (sorted.length <= 2) return sorted;
  const turn = (a: Vec2, b: Vec2, c: Vec2) =>
    (b[0] - a[0]) * (c[1] - a[1]) -
    (b[1] - a[1]) * (c[0] - a[0]);
  const half = (values: Vec2[]) => {
    const result: Vec2[] = [];
    values.forEach((point) => {
      while (
        result.length >= 2 &&
        turn(result[result.length - 2], result[result.length - 1], point) <= 1e-10
      )
        result.pop();
      result.push(point);
    });
    return result;
  };
  return [
    ...half(sorted).slice(0, -1),
    ...half([...sorted].reverse()).slice(0, -1),
  ];
}

export function makeProjectedEntity(
  body: Body,
  plane: SketchPlane,
  mode: ProjectionMode,
  edgeIndex = 0,
  id = uid("entity"),
  frame?: PlaneFrame,
): SketchEntity {
  let {
    center: [cx, cy],
    width,
    height,
  } = planeFootprint(body, plane);
  let projectedOutline: Vec2[] | null = null;
  if (frame || body.projectionEnvelope?.length) {
    const projectionFrame = frame ?? axisAlignedWorkplaneFrame({
      plane,
      origin: [0, 0, 0],
      normal: 1,
    });
    const localPoints = body.projectionEnvelope?.length
      ? body.projectionEnvelope.map((point) =>
          point.map((value, axis) => value * body.size[axis]) as Vec3,
        )
      : Array.from({ length: 8 }, (_, index) =>
          body.size.map(
            (size, axis) => ((index >> axis) & 1 ? 1 : -1) * size / 2,
          ) as Vec3,
        );
    const projected = localPoints.map((local) => {
      const world = bodyLocalPointToWorld(body, local);
      const delta = world.map(
        (value, axis) => value - projectionFrame.origin[axis],
      ) as Vec3;
      return [
        frameDot(delta, projectionFrame.xAxis),
        frameDot(delta, projectionFrame.yAxis),
      ] as Vec2;
    });
    projectedOutline = convexProjectionHull(projected);
    const xs = projected.map((point) => point[0]);
    const ys = projected.map((point) => point[1]);
    const minimumX = Math.min(...xs), maximumX = Math.max(...xs);
    const minimumY = Math.min(...ys), maximumY = Math.max(...ys);
    cx = (minimumX + maximumX) / 2;
    cy = (minimumY + maximumY) / 2;
    width = Math.max(0.001, maximumX - minimumX);
    height = Math.max(0.001, maximumY - minimumY);
  }
  const projection: ProjectionRef = {
    bodyId: body.id,
    mode,
    edgeIndex,
    linked: true,
  };
  const common: SketchEntityBase = { id, projected: true, projection };
  if (mode === "point" && projectedOutline?.length) {
    const point = projectedOutline[((edgeIndex % projectedOutline.length) + projectedOutline.length) % projectedOutline.length];
    return { ...common, kind: "point", x: point[0], y: point[1] };
  }
  if (mode === "point")
    return { ...common, kind: "point", x: cx + width / 2, y: cy + height / 2 };
  if (
    mode === "silhouette" &&
    ["Cylinder", "Sphere", "Cone", "Torus", "Tube"].includes(body.shape)
  ) {
    return {
      ...common,
      kind: "circle",
      x: cx,
      y: cy,
      radius: Math.max(0.1, Math.max(width, height) / 2),
    };
  }
  const corners: Vec2[] = [
    [cx - width / 2, cy - height / 2],
    [cx + width / 2, cy - height / 2],
    [cx + width / 2, cy + height / 2],
    [cx - width / 2, cy + height / 2],
  ];
  if (mode === "edge") {
    if (projectedOutline && projectedOutline.length >= 2) {
      const index = ((edgeIndex % projectedOutline.length) + projectedOutline.length) % projectedOutline.length;
      return {
        ...common,
        kind: "polyline",
        points: [
          projectedOutline[index],
          projectedOutline[(index + 1) % projectedOutline.length],
        ],
        closed: false,
      };
    }
    const index = ((edgeIndex % 4) + 4) % 4;
    return {
      ...common,
      kind: "polyline",
      points: [corners[index], corners[(index + 1) % 4]],
      closed: false,
    };
  }
  if (projectedOutline && projectedOutline.length >= 3)
    return {
      ...common,
      kind: "polyline",
      points: projectedOutline,
      closed: true,
    };
  return {
    ...common,
    kind: "rectangle",
    x: corners[0][0],
    y: corners[0][1],
    width,
    height,
  };
}

export function syncSketchProjections(sketch: Sketch, bodies: Body[]): Sketch {
  const localOrigin: Vec2 = sketch.origin
    ? sketch.plane === "XY"
      ? [sketch.origin[0], sketch.origin[1]]
      : sketch.plane === "XZ"
        ? [sketch.origin[0], sketch.origin[2]]
        : [sketch.origin[1], sketch.origin[2]]
    : [0, 0];
  return {
    ...sketch,
    constraints: sketch.constraints ?? [],
    dimensions: sketch.dimensions ?? [],
    entities: sketch.entities.map((entity) => {
      if (!entity.projection?.linked) return entity;
      const body = bodies.find(
        (candidate) => candidate.id === entity.projection!.bodyId,
      );
      if (!body) return entity;
      const projected = makeProjectedEntity(
        body,
        sketch.plane,
        entity.projection.mode,
        entity.projection.edgeIndex,
        entity.id,
        sketch.frame,
      );
      return sketch.coordinateSpace === "local" && !sketch.frame
        ? translateSketchEntity(projected, [-localOrigin[0], -localOrigin[1]])
        : projected;
    }),
  };
}

export function syncSketchWorkplane(
  sketch: Sketch,
  workplanes: Workplane[],
  bodies: Body[],
): Sketch {
  if (!sketch.workplaneId) return structuredClone(sketch);
  const workplane = workplanes.find((item) => item.id === sketch.workplaneId);
  if (!workplane) return structuredClone(sketch);
  const resolved = resolveWorkplane(workplane, bodies);
  return {
    ...structuredClone(sketch),
    plane: resolved.plane,
    origin: resolved.origin,
    normal: resolved.normal,
    attachment: resolved.attachment
      ? structuredClone(resolved.attachment)
      : undefined,
    coordinateSpace: "local",
    frame: resolved.frame ? structuredClone(resolved.frame) : undefined,
  };
}

