import JSZip from "jszip";
import type { BenchProject, MeshDiagnostics, Vec3 } from "./benchcad-model";

export type MeshFormat = "STL" | "OBJ" | "3MF";
export interface ParsedMesh {
  vertices: number[];
  indices: number[];
  format: MeshFormat;
  objectCount: number;
  detectedUnits?: BenchProject["units"];
  detectedUnitLabel?: string;
}
export interface MeshRepairOptions {
  deduplicate: boolean;
  removeDegenerate: boolean;
  recalculateNormals: boolean;
  flipWinding: boolean;
  closeSmallHoles: boolean;
}
export interface PreparedMesh extends ParsedMesh {
  diagnostics: MeshDiagnostics;
  baseDimensions: Vec3;
  center: Vec3;
  repairs: string[];
  importUnits: BenchProject["units"];
}

const EPS = 1e-9;
const UNIT_METERS: Record<BenchProject["units"], number> = {
  mm: 0.001,
  cm: 0.01,
  in: 0.0254,
  m: 1,
};

function key(x: number, y: number, z: number) {
  return `${Math.round(x * 1e7)},${Math.round(y * 1e7)},${Math.round(z * 1e7)}`;
}

function bounds(vertices: number[]) {
  const min: Vec3 = [Infinity, Infinity, Infinity];
  const max: Vec3 = [-Infinity, -Infinity, -Infinity];
  for (let i = 0; i < vertices.length; i += 3) {
    for (let axis = 0; axis < 3; axis += 1) {
      min[axis] = Math.min(min[axis], vertices[i + axis]);
      max[axis] = Math.max(max[axis], vertices[i + axis]);
    }
  }
  if (!vertices.length) return { min: [0, 0, 0] as Vec3, max: [0, 0, 0] as Vec3 };
  return { min, max };
}

function canonical(vertices: number[], indices: number[]) {
  const unique: number[] = [];
  const map = new Map<string, number>();
  const remap = new Array(vertices.length / 3);
  for (let i = 0; i < vertices.length; i += 3) {
    const k = key(vertices[i], vertices[i + 1], vertices[i + 2]);
    let next = map.get(k);
    if (next === undefined) {
      next = unique.length / 3;
      map.set(k, next);
      unique.push(vertices[i], vertices[i + 1], vertices[i + 2]);
    }
    remap[i / 3] = next;
  }
  return { vertices: unique, indices: indices.map((index) => remap[index]), duplicateVertices: remap.length - unique.length / 3 };
}

function triangleArea2(vertices: number[], a: number, b: number, c: number) {
  const ax = vertices[b * 3] - vertices[a * 3];
  const ay = vertices[b * 3 + 1] - vertices[a * 3 + 1];
  const az = vertices[b * 3 + 2] - vertices[a * 3 + 2];
  const bx = vertices[c * 3] - vertices[a * 3];
  const by = vertices[c * 3 + 1] - vertices[a * 3 + 1];
  const bz = vertices[c * 3 + 2] - vertices[a * 3 + 2];
  const cx = ay * bz - az * by;
  const cy = az * bx - ax * bz;
  const cz = ax * by - ay * bx;
  return Math.hypot(cx, cy, cz);
}

export function diagnoseMesh(verticesInput: number[], indicesInput: number[]): MeshDiagnostics {
  const sourceVertexCount = verticesInput.length / 3;
  const canonicalMesh = canonical(verticesInput, indicesInput);
  const { vertices, indices } = canonicalMesh;
  const edgeMap = new Map<string, Array<[number, number, number]>>();
  const adjacency = Array.from({ length: Math.floor(indices.length / 3) }, () => new Set<number>());
  let degenerateTriangles = 0;
  let signedVolume = 0;
  for (let i = 0; i + 2 < indices.length; i += 3) {
    const tri = i / 3;
    const a = indices[i], b = indices[i + 1], c = indices[i + 2];
    if (a === b || b === c || c === a || triangleArea2(vertices, a, b, c) <= EPS) degenerateTriangles += 1;
    const edges: Array<[number, number]> = [[a, b], [b, c], [c, a]];
    for (const [from, to] of edges) {
      const k = from < to ? `${from}:${to}` : `${to}:${from}`;
      const owners = edgeMap.get(k) ?? [];
      owners.push([tri, from, to]);
      edgeMap.set(k, owners);
    }
    const ax = vertices[a * 3], ay = vertices[a * 3 + 1], az = vertices[a * 3 + 2];
    const bx = vertices[b * 3], by = vertices[b * 3 + 1], bz = vertices[b * 3 + 2];
    const cx = vertices[c * 3], cy = vertices[c * 3 + 1], cz = vertices[c * 3 + 2];
    signedVolume += (ax * (by * cz - bz * cy) - ay * (bx * cz - bz * cx) + az * (bx * cy - by * cx)) / 6;
  }
  let boundaryEdges = 0, nonManifoldEdges = 0, inconsistentWindingEdges = 0;
  for (const owners of edgeMap.values()) {
    if (owners.length === 1) boundaryEdges += 1;
    if (owners.length > 2) nonManifoldEdges += 1;
    if (owners.length === 2) {
      adjacency[owners[0][0]].add(owners[1][0]);
      adjacency[owners[1][0]].add(owners[0][0]);
      if (owners[0][1] === owners[1][1] && owners[0][2] === owners[1][2]) inconsistentWindingEdges += 1;
    }
  }
  let connectedComponents = 0;
  const seen = new Set<number>();
  for (let i = 0; i < adjacency.length; i += 1) {
    if (seen.has(i)) continue;
    connectedComponents += 1;
    const stack = [i];
    seen.add(i);
    while (stack.length) for (const next of adjacency[stack.pop()!]) if (!seen.has(next)) { seen.add(next); stack.push(next); }
  }
  const box = bounds(vertices);
  const dimensions = box.max.map((value, axis) => value - box.min[axis]) as Vec3;
  const scale = Math.max(...dimensions, 1);
  const zeroVolume = Math.abs(signedVolume) <= scale ** 3 * 1e-10;
  return {
    vertexCount: sourceVertexCount,
    triangleCount: Math.floor(indices.length / 3),
    duplicateVertices: canonicalMesh.duplicateVertices,
    degenerateTriangles,
    boundaryEdges,
    nonManifoldEdges,
    inconsistentWindingEdges,
    connectedComponents,
    signedVolume,
    volume: Math.abs(signedVolume),
    dimensions,
    watertight: boundaryEdges === 0,
    manifold: boundaryEdges === 0 && nonManifoldEdges === 0,
    invertedWinding: signedVolume < -EPS,
    zeroVolume,
    extremelyThin: Math.min(...dimensions) <= scale * 1e-5,
  };
}

function parseAsciiStl(text: string): ParsedMesh {
  const vertices: number[] = [], indices: number[] = [];
  const matches = [...text.matchAll(/vertex\s+([-+\deE.]+)\s+([-+\deE.]+)\s+([-+\deE.]+)/gi)];
  if (matches.length < 3 || matches.length % 3) throw new Error("STL does not contain complete triangular facets.");
  for (const match of matches) {
    vertices.push(Number(match[1]), Number(match[2]), Number(match[3]));
    indices.push(indices.length);
  }
  return { vertices, indices, format: "STL", objectCount: 1 };
}

function parseBinaryStl(buffer: ArrayBuffer): ParsedMesh {
  const view = new DataView(buffer);
  if (view.byteLength < 84) throw new Error("Binary STL is truncated.");
  const triangles = view.getUint32(80, true);
  if (84 + triangles * 50 > view.byteLength) throw new Error("Binary STL facet table is truncated.");
  const vertices: number[] = [], indices: number[] = [];
  for (let tri = 0; tri < triangles; tri += 1) {
    let offset = 84 + tri * 50 + 12;
    for (let corner = 0; corner < 3; corner += 1) {
      vertices.push(view.getFloat32(offset, true), view.getFloat32(offset + 4, true), view.getFloat32(offset + 8, true));
      indices.push(indices.length);
      offset += 12;
    }
  }
  return { vertices, indices, format: "STL", objectCount: 1 };
}

export function parseStl(buffer: ArrayBuffer): ParsedMesh {
  const view = new DataView(buffer);
  if (buffer.byteLength >= 84) {
    const triangles = view.getUint32(80, true);
    if (84 + triangles * 50 === buffer.byteLength) return parseBinaryStl(buffer);
  }
  return parseAsciiStl(new TextDecoder().decode(buffer));
}

export function parseObj(text: string): ParsedMesh {
  const source: Vec3[] = [], vertices: number[] = [], indices: number[] = [];
  let objectCount = 0;
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (line.startsWith("v ")) {
      const values = line.slice(2).trim().split(/\s+/).slice(0, 3).map(Number);
      if (values.length === 3 && values.every(Number.isFinite)) source.push(values as Vec3);
    } else if (/^[og]\s+/.test(line)) objectCount += 1;
    else if (line.startsWith("f ")) {
      const refs = line.slice(2).trim().split(/\s+/).map((token) => Number(token.split("/")[0])).map((index) => index < 0 ? source.length + index : index - 1);
      for (let i = 1; i + 1 < refs.length; i += 1) {
        for (const ref of [refs[0], refs[i], refs[i + 1]]) {
          if (!source[ref]) throw new Error("OBJ face references a missing vertex.");
          vertices.push(...source[ref]); indices.push(indices.length);
        }
      }
    }
  }
  if (!indices.length) throw new Error("OBJ does not contain polygon faces.");
  return { vertices, indices, format: "OBJ", objectCount: Math.max(1, objectCount) };
}

function unitFrom3mf(value?: string) {
  const name = (value ?? "millimeter").toLowerCase();
  if (name === "inch") return { unit: "in" as const, scale: 1, label: "inch" };
  if (name === "meter") return { unit: "m" as const, scale: 1, label: "meter" };
  if (name === "centimeter") return { unit: "cm" as const, scale: 1, label: "centimeter" };
  if (name === "micron") return { unit: "mm" as const, scale: 0.001, label: "micron (normalized to mm)" };
  if (name === "foot") return { unit: "in" as const, scale: 12, label: "foot (normalized to in)" };
  return { unit: "mm" as const, scale: 1, label: name || "millimeter" };
}

function transformPoint(point: Vec3, matrix?: number[]): Vec3 {
  if (!matrix || matrix.length !== 12) return point;
  const [x, y, z] = point;
  return [x * matrix[0] + y * matrix[3] + z * matrix[6] + matrix[9], x * matrix[1] + y * matrix[4] + z * matrix[7] + matrix[10], x * matrix[2] + y * matrix[5] + z * matrix[8] + matrix[11]];
}

export async function parse3mf(buffer: ArrayBuffer): Promise<ParsedMesh> {
  const zip = await JSZip.loadAsync(buffer);
  const modelFile = Object.values(zip.files).find((file) => /3d\/.*\.model$/i.test(file.name));
  if (!modelFile) throw new Error("3MF archive does not contain a model part.");
  const xml = await modelFile.async("text");
  const attributes = (source: string) => Object.fromEntries(
    [...source.matchAll(/([:\w-]+)\s*=\s*["']([^"']*)["']/g)].map((match) => [match[1].toLowerCase(), match[2]]),
  );
  const modelTag = xml.match(/<(?:\w+:)?model\b([^>]*)>/i);
  if (!modelTag) throw new Error("3MF model XML is invalid.");
  const info = unitFrom3mf(attributes(modelTag[1]).unit);
  const objects = new Map<string, { vertices: Vec3[]; triangles: number[] }>();
  for (const match of xml.matchAll(/<(?:\w+:)?object\b([^>]*)>([\s\S]*?)<\/(?:\w+:)?object>/gi)) {
    const objectAttributes = attributes(match[1]);
    const local = [...match[2].matchAll(/<(?:\w+:)?vertex\b([^>]*)\/?\s*>/gi)].map((vertex) => {
      const value = attributes(vertex[1]);
      return [Number(value.x), Number(value.y), Number(value.z)] as Vec3;
    });
    const triangles = [...match[2].matchAll(/<(?:\w+:)?triangle\b([^>]*)\/?\s*>/gi)].flatMap((triangle) => {
      const value = attributes(triangle[1]);
      return [Number(value.v1), Number(value.v2), Number(value.v3)];
    });
    if (local.length && triangles.length) objects.set(objectAttributes.id ?? String(objects.size + 1), { vertices: local, triangles });
  }
  const vertices: number[] = [], indices: number[] = [];
  const items = [...xml.matchAll(/<(?:\w+:)?item\b([^>]*)\/?\s*>/gi)].map((match) => attributes(match[1]));
  const builds: Array<Record<string, string>> = items.length ? items : [...objects.keys()].map((objectid) => ({ objectid }));
  for (const item of builds) {
    const mesh = objects.get(item.objectid ?? "");
    if (!mesh) continue;
    const matrix = item.transform?.trim().split(/\s+/).map(Number);
    const offset = vertices.length / 3;
    mesh.vertices.forEach((point) => vertices.push(...transformPoint(point, matrix).map((value) => value * info.scale)));
    indices.push(...mesh.triangles.map((index) => offset + index));
  }
  if (!indices.length) throw new Error("3MF does not contain a triangular build mesh.");
  return { vertices, indices, format: "3MF", objectCount: builds.length, detectedUnits: info.unit, detectedUnitLabel: info.label };
}

export async function parseMeshFile(buffer: ArrayBuffer, format: MeshFormat) {
  if (format === "STL") return parseStl(buffer);
  if (format === "OBJ") return parseObj(new TextDecoder().decode(buffer));
  return parse3mf(buffer);
}

function orientTriangles(vertices: number[], indices: number[]) {
  const edges = new Map<string, Array<{ tri: number; from: number; to: number }>>();
  for (let i = 0; i < indices.length; i += 3) for (const [from, to] of [[indices[i], indices[i + 1]], [indices[i + 1], indices[i + 2]], [indices[i + 2], indices[i]]]) {
    const k = from < to ? `${from}:${to}` : `${to}:${from}`;
    edges.set(k, [...(edges.get(k) ?? []), { tri: i / 3, from, to }]);
  }
  const flip = new Map<number, boolean>([[0, false]]), queue = [0];
  while (queue.length) {
    const tri = queue.shift()!;
    for (let j = 0; j < 3; j += 1) {
      const from = indices[tri * 3 + j], to = indices[tri * 3 + (j + 1) % 3];
      const k = from < to ? `${from}:${to}` : `${to}:${from}`;
      for (const owner of edges.get(k) ?? []) if (!flip.has(owner.tri)) {
        flip.set(owner.tri, Boolean(flip.get(tri)) !== (owner.from === from && owner.to === to)); queue.push(owner.tri);
      }
    }
  }
  for (const [tri, shouldFlip] of flip) if (shouldFlip) [indices[tri * 3 + 1], indices[tri * 3 + 2]] = [indices[tri * 3 + 2], indices[tri * 3 + 1]];
  if (diagnoseMesh(vertices, indices).signedVolume < 0) for (let i = 0; i < indices.length; i += 3) [indices[i + 1], indices[i + 2]] = [indices[i + 2], indices[i + 1]];
}

export function repairMesh(parsed: ParsedMesh, options: MeshRepairOptions) {
  let vertices = [...parsed.vertices], indices = [...parsed.indices];
  const repairs: string[] = [];
  if (options.deduplicate) { const result = canonical(vertices, indices); vertices = result.vertices; indices = result.indices; repairs.push("Deduplicated vertices"); }
  if (options.removeDegenerate) { const next: number[] = []; for (let i = 0; i < indices.length; i += 3) if (triangleArea2(vertices, indices[i], indices[i + 1], indices[i + 2]) > EPS) next.push(indices[i], indices[i + 1], indices[i + 2]); indices = next; repairs.push("Removed degenerate triangles"); }
  if (options.recalculateNormals) { orientTriangles(vertices, indices); repairs.push("Reoriented triangle normals"); }
  if (options.flipWinding) { for (let i = 0; i < indices.length; i += 3) [indices[i + 1], indices[i + 2]] = [indices[i + 2], indices[i + 1]]; repairs.push("Flipped winding"); }
  if (options.closeSmallHoles) {
    const edgeOwners = new Map<string, [number, number][]>();
    for (let i = 0; i < indices.length; i += 3) for (const [a, b] of [[indices[i], indices[i + 1]], [indices[i + 1], indices[i + 2]], [indices[i + 2], indices[i]]]) { const k = a < b ? `${a}:${b}` : `${b}:${a}`; edgeOwners.set(k, [...(edgeOwners.get(k) ?? []), [a, b]]); }
    const boundary = [...edgeOwners.values()].filter((owners) => owners.length === 1).map((owners) => owners[0]);
    const unused = [...boundary];
    while (unused.length) {
      const first = unused.shift()!, loop = [first[0], first[1]];
      while (loop.length <= 64 && loop.at(-1) !== loop[0]) { const at = unused.findIndex(([a, b]) => a === loop.at(-1) || b === loop.at(-1)); if (at < 0) break; const [a, b] = unused.splice(at, 1)[0]; loop.push(a === loop.at(-1) ? b : a); }
      if (loop.length >= 4 && loop.length <= 65 && loop.at(-1) === loop[0]) { const ring = loop.slice(0, -1); const center = ring.reduce((sum, index) => [sum[0] + vertices[index * 3], sum[1] + vertices[index * 3 + 1], sum[2] + vertices[index * 3 + 2]] as Vec3, [0, 0, 0] as Vec3).map((value) => value / ring.length) as Vec3; const ci = vertices.length / 3; vertices.push(...center); for (let i = 0; i < ring.length; i += 1) indices.push(ring[i], ring[(i + 1) % ring.length], ci); }
    }
    repairs.push("Closed small boundary loops");
  }
  return { ...parsed, vertices, indices, repairs };
}

export function prepareMeshForProject(parsed: ParsedMesh, sourceUnits: BenchProject["units"], projectUnits: BenchProject["units"], options: MeshRepairOptions): PreparedMesh {
  const repaired = repairMesh(parsed, options);
  const scale = UNIT_METERS[sourceUnits] / UNIT_METERS[projectUnits];
  let vertices = repaired.vertices.map((value) => value * scale);
  const box = bounds(vertices);
  const center = box.min.map((value, axis) => (value + box.max[axis]) / 2) as Vec3;
  vertices = vertices.map((value, index) => value - center[index % 3]);
  const diagnostics = diagnoseMesh(vertices, repaired.indices);
  return { ...repaired, vertices, diagnostics, baseDimensions: diagnostics.dimensions, center, importUnits: sourceUnits };
}

export function meshHasSeriousIssues(diagnostics: MeshDiagnostics) {
  return diagnostics.boundaryEdges > 0 || diagnostics.nonManifoldEdges > 0 || diagnostics.inconsistentWindingEdges > 0 || diagnostics.degenerateTriangles > 0 || diagnostics.zeroVolume || diagnostics.invertedWinding;
}

export function arrayBufferToBase64(buffer: ArrayBuffer) {
  const bytes = new Uint8Array(buffer); let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(binary);
}

export function base64ToUint8Array(value: string) {
  const binary = atob(value), bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
