import { migrateProject, type BenchProject } from "@/lib/benchcad-model";

const DB_NAME = "benchcad-local";
const STORE_NAME = "projects";

export interface LocalStorageHealth {
  available: boolean;
  writable: boolean;
  projectCount: number;
  usageBytes: number | null;
  quotaBytes: number | null;
  persisted: boolean | null;
  message: string;
}

function openDatabase(): Promise<IDBDatabase> {
  if (typeof indexedDB === "undefined")
    return Promise.reject(new Error("IndexedDB is not available in this browser"));
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = () => {
      const database = request.result;
      if (!database.objectStoreNames.contains(STORE_NAME))
        database.createObjectStore(STORE_NAME, { keyPath: "id" });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
    request.onblocked = () =>
      reject(new Error("BENCHCAD storage is blocked by another browser tab"));
  });
}

export async function saveLocalProject(project: BenchProject) {
  const database = await openDatabase();
  await new Promise<void>((resolve, reject) => {
    const transaction = database.transaction(STORE_NAME, "readwrite");
    transaction.objectStore(STORE_NAME).put(project);
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error);
  });
  database.close();
}

export async function listLocalProjects(): Promise<BenchProject[]> {
  const database = await openDatabase();
  const projects = await new Promise<BenchProject[]>((resolve, reject) => {
    const request = database
      .transaction(STORE_NAME)
      .objectStore(STORE_NAME)
      .getAll();
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
  database.close();
  return projects
    .flatMap((project) => {
      try {
        return [migrateProject(project)];
      } catch {
        return [];
      }
    })
    .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
}

export async function saveLocalProjects(projects: BenchProject[]) {
  const database = await openDatabase();
  await new Promise<void>((resolve, reject) => {
    const transaction = database.transaction(STORE_NAME, "readwrite");
    const store = transaction.objectStore(STORE_NAME);
    projects.forEach((project) => store.put(migrateProject(project)));
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error);
    transaction.onabort = () => reject(transaction.error);
  });
  database.close();
}

export async function inspectLocalStorage(): Promise<LocalStorageHealth> {
  try {
    const database = await openDatabase();
    const projectCount = await new Promise<number>((resolve, reject) => {
      const request = database.transaction(STORE_NAME).objectStore(STORE_NAME).count();
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
    database.close();

    const estimate = await navigator.storage?.estimate?.().catch(() => undefined);
    const persisted = await navigator.storage?.persisted?.().catch(() => null) ?? null;
    return {
      available: true,
      writable: true,
      projectCount,
      usageBytes: estimate?.usage ?? null,
      quotaBytes: estimate?.quota ?? null,
      persisted,
      message: persisted
        ? "Browser storage is persistent"
        : "Browser storage may be reclaimed; keep a recovery backup",
    };
  } catch (error) {
    return {
      available: false,
      writable: false,
      projectCount: 0,
      usageBytes: null,
      quotaBytes: null,
      persisted: null,
      message: error instanceof Error ? error.message : "Local storage is unavailable",
    };
  }
}

export async function requestPersistentLocalStorage() {
  if (!navigator.storage?.persist) return null;
  return navigator.storage.persist();
}

export async function clearLocalProjects() {
  const database = await openDatabase();
  await new Promise<void>((resolve, reject) => {
    const request = database
      .transaction(STORE_NAME, "readwrite")
      .objectStore(STORE_NAME)
      .clear();
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
  database.close();
}
