import type { RevolveAxisKind, Sketch, Vec2, Vec3 } from "./benchcad-model";

export interface RevolveProfileResult {
  profile: Vec2[];
  profileHoles: Vec2[][];
  position: Vec3;
  size: Vec3;
  axisOrigin: Vec2;
  axisDirection: Vec2;
  radialDirection: Vec3;
  axisDirection3d: Vec3;
}

const dot2 = (a: Vec2, b: Vec2) => a[0] * b[0] + a[1] * b[1];
const dot3 = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec3, b: Vec3): Vec3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
const scale3 = (a: Vec3, value: number): Vec3 => [a[0] * value, a[1] * value, a[2] * value];
const add3 = (a: Vec3, b: Vec3): Vec3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];

function planeBasis(sketch: Sketch) {
  if (sketch.frame)
    return {
      u: sketch.frame.xAxis,
      v: sketch.frame.yAxis,
      normal: sketch.frame.normal,
    };
  if (sketch.plane === "XY") return { u: [1, 0, 0] as Vec3, v: [0, 1, 0] as Vec3, normal: [0, 0, sketch.normal ?? 1] as Vec3 };
  if (sketch.plane === "XZ") return { u: [1, 0, 0] as Vec3, v: [0, 0, 1] as Vec3, normal: [0, sketch.normal ?? 1, 0] as Vec3 };
  return { u: [0, 1, 0] as Vec3, v: [0, 0, 1] as Vec3, normal: [sketch.normal ?? 1, 0, 0] as Vec3 };
}

export function resolveRevolveAxis(sketch: Sketch, kind: RevolveAxisKind, axisEntityId?: string) {
  if (kind === "horizontal") return { origin: [0, 0] as Vec2, direction: [1, 0] as Vec2 };
  if (kind === "vertical") return { origin: [0, 0] as Vec2, direction: [0, 1] as Vec2 };
  const entity = sketch.entities.find((item) => item.id === axisEntityId);
  if (!entity || entity.kind !== "polyline" || !entity.construction || entity.points.length !== 2)
    throw new Error("Select one two-point construction line from this sketch as the revolve axis.");
  const [a, b] = entity.points;
  const length = Math.hypot(b[0] - a[0], b[1] - a[1]);
  if (length <= 1e-8) throw new Error("The construction axis has zero length.");
  return { origin: [...a] as Vec2, direction: [(b[0] - a[0]) / length, (b[1] - a[1]) / length] as Vec2 };
}

export function buildRevolveProfiles(
  sketch: Sketch,
  profiles: Vec2[][],
  axisKind: RevolveAxisKind,
  axisEntityId?: string,
): RevolveProfileResult {
  if (!profiles.length || profiles[0].length < 3) throw new Error("Select at least one closed profile to revolve.");
  const axis = resolveRevolveAxis(sketch, axisKind, axisEntityId);
  let direction = axis.direction;
  let perpendicular: Vec2 = [-direction[1], direction[0]];
  const signed = profiles.flat().map((point) => dot2([point[0] - axis.origin[0], point[1] - axis.origin[1]], perpendicular));
  const tolerance = Math.max(1e-7, Math.max(...signed.map(Math.abs), 1) * 1e-8);
  if (Math.min(...signed) < -tolerance && Math.max(...signed) > tolerance)
    throw new Error("The selected profile crosses the revolve axis. Move the profile to one side or choose another axis.");
  if (signed.reduce((sum, value) => sum + value, 0) < 0) perpendicular = [-perpendicular[0], -perpendicular[1]];
  const basis = planeBasis(sketch);
  let radialDirection = add3(scale3(basis.u, perpendicular[0]), scale3(basis.v, perpendicular[1]));
  let axisDirection3d = add3(scale3(basis.u, direction[0]), scale3(basis.v, direction[1]));
  if (dot3(cross(radialDirection, axisDirection3d), basis.normal) < 0) {
    direction = [-direction[0], -direction[1]];
    axisDirection3d = scale3(axisDirection3d, -1);
  }
  const convert = (profile: Vec2[]) => profile.map((point) => {
    const delta: Vec2 = [point[0] - axis.origin[0], point[1] - axis.origin[1]];
    return [Math.max(0, dot2(delta, perpendicular)), dot2(delta, direction)] as Vec2;
  });
  const converted = profiles.map(convert);
  const localOrigin = sketch.coordinateSpace === "local" && sketch.origin ? sketch.origin : ([0, 0, 0] as Vec3);
  const position = add3(localOrigin, add3(scale3(basis.u, axis.origin[0]), scale3(basis.v, axis.origin[1])));
  const radii = converted.flat().map((point) => point[0]);
  const axial = converted.flat().map((point) => point[1]);
  const radius = Math.max(...radii, 0.001);
  const axialSpan = Math.max(0.001, Math.max(...axial) - Math.min(...axial));
  radialDirection = radialDirection.map((value) => Math.abs(value) < 1e-12 ? 0 : value) as Vec3;
  axisDirection3d = axisDirection3d.map((value) => Math.abs(value) < 1e-12 ? 0 : value) as Vec3;
  return {
    profile: converted[0],
    profileHoles: converted.slice(1),
    position,
    size: [radius * 2, radius * 2, axialSpan],
    axisOrigin: axis.origin,
    axisDirection: direction,
    radialDirection,
    axisDirection3d,
  };
}
