function downloadBlob(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 500);
}

function formatMass(mass: number) {
  return mass < 1
    ? `${Number((mass * 1000).toFixed(3))} g`
    : `${Number(mass.toFixed(4))} kg`;
}

function formatMeasure(value: number, precision = 4) {
  if (Math.abs(value) >= 1e6 || (Math.abs(value) > 0 && Math.abs(value) < 1e-3))
    return value.toExponential(3);
  return Number(value.toFixed(precision)).toLocaleString();
}

function StatusLed({
  status,
}: {
  status: "unsaved" | "saving" | "saved" | "recovery" | "error";
}) {
  return (
    <span className={`save-state save-${status}`} aria-live="polite">
      <span className="status-dot" />
      {status === "unsaved"
        ? "Unsaved"
        : status === "saving"
          ? "Saving"
          : status === "saved"
            ? "Saved locally"
            : status === "recovery"
              ? "Recovery available"
              : "Save error"}
    </span>
  );
}

function TinyButton({
  label,
  children,
  onClick,
  active,
  disabled = false,
}: {
  label: string;
  children: React.ReactNode;
  onClick?: () => void;
  active?: boolean;
  disabled?: boolean;
}) {
  return (
    <button
      className={`tiny-button ${active ? "is-active" : ""}`}
      onClick={onClick}
      disabled={disabled}
      title={label}
      aria-label={label}
      aria-pressed={active === undefined ? undefined : active}
    >
      {children}
    </button>
  );
}

function NumberField({
  label,
  value,
  suffix,
  onCommit,
  min = -10000,
  max,
  disabled = false,
}: {
  label: string;
  value: number;
  suffix: string;
  onCommit: (value: number) => void;
  min?: number;
  max?: number;
  disabled?: boolean;
}) {
  return (
    <label className="number-field">
      <span>{label}</span>
      <span className="numeric-wrap">
        <input
          key={`${label}-${value}`}
          type="number"
          defaultValue={Number(value.toFixed(3))}
          min={min}
          max={max}
          disabled={disabled}
          step="0.1"
          onKeyDown={(event) => {
            if (event.key === "Enter") event.currentTarget.blur();
            if (event.key === "Escape") {
              event.currentTarget.value = String(value);
              event.currentTarget.blur();
            }
          }}
          onBlur={(event) => {
            const next = Number(event.currentTarget.value);
            if (Number.isFinite(next) && next !== value) onCommit(next);
          }}
        />
        <em>{suffix}</em>
      </span>
    </label>
  );
}

