  function refreshAssociativeSketches(next: BenchProject) {
    const rebuilt = reconstruct(next.features);
    const bodies = rebuilt.bodies;
    next.features.forEach((feature) => {
      if (feature.sketchSnapshot) {
        feature.sketchSnapshot = syncSketchWorkplane(
          feature.sketchSnapshot,
          rebuilt.workplanes,
          bodies,
        );
        feature.sketchSnapshot = syncSketchProjections(
          feature.sketchSnapshot,
          bodies,
        );
      }
    });
    next.features
      .filter(
        (feature) =>
          ["Extrude", "Revolve", "Sweep", "Loft"].includes(feature.type) &&
          feature.snapshot,
      )
      .forEach((derived) => {
        const sketch = next.features.find(
          (feature) =>
            feature.sketchSnapshot?.id === derived.parameters.sketchId,
        )?.sketchSnapshot;
        const ids = (derived.parameters.entityIds as string[] | undefined) ?? [
          String(derived.parameters.entityId ?? ""),
        ];
        let rebuilt: Body | null = null;
        let rebuildMessage = "The source sketch is not ready for this feature.";
        try {
          rebuilt = derived.type === "Sweep"
            ? sweepBodyFromFeature(derived, next.features.flatMap((feature) => feature.sketchSnapshot ? [feature.sketchSnapshot] : []), derived.snapshot!)
            : derived.type === "Loft"
              ? loftBodyFromFeature(derived, next.features.flatMap((feature) => feature.sketchSnapshot ? [feature.sketchSnapshot] : []), derived.snapshot!)
          : derived.type === "Extrude" && sketch
            ? makeExtrusionBody(
                sketch,
                ids,
                Number(derived.parameters.distance ?? derived.snapshot!.size[2]),
                String(derived.parameters.operation ?? "new") as
                  "new" | "join" | "cut",
                derived.snapshot,
                bodies,
              )
            : derived.type === "Revolve" && sketch
            ? makeRevolutionBody(
                sketch,
                ids,
                Number(derived.parameters.angle ?? 360),
                String(derived.parameters.axisKind ?? "horizontal") as RevolveAxisKind,
                derived.parameters.axisEntityId
                  ? String(derived.parameters.axisEntityId)
                  : undefined,
                String(derived.parameters.operation ?? "new") as
                  "new" | "join" | "cut",
                derived.snapshot,
                bodies,
              )
            : null;
        } catch (error) {
          rebuildMessage = error instanceof Error ? error.message : rebuildMessage;
          rebuilt = null;
        }
        if (rebuilt) {
          const previous = derived.snapshot!;
          derived.snapshot = rebuilt;
          derived.status = "valid";
          delete derived.parameters.profileWarning;
          propagateDerivedBodyRebuild(
            next.features,
            derived.id,
            previous,
            rebuilt,
          );
        } else {
          derived.status = "warning";
          derived.parameters.profileWarning = rebuildMessage;
        }
      });
  }

