  function componentFeature(
    type: string,
    name: string,
    component: ComponentDefinition,
    sequence: number,
    parameters: Record<string, unknown> = {},
    occurrence?: ComponentOccurrence,
  ) {
    const feature = makeFeature(
      type,
      name,
      sequence,
      undefined,
      parameters,
      type === "Create component" ? [] : [component.id],
    );
    feature.componentId = component.id;
    feature.componentSnapshot = structuredClone(component);
    if (occurrence) {
      feature.occurrenceSnapshot = structuredClone(occurrence);
      if (occurrence.parentOccurrenceId)
        feature.inputIds = [occurrence.parentOccurrenceId];
    }
    feature.outputIds = [
      component.id,
      ...(occurrence ? [occurrence.id] : []),
    ];
    return feature;
  }

  function occurrenceFeature(
    type: string,
    name: string,
    occurrence: ComponentOccurrence,
    sequence: number,
    parameters: Record<string, unknown> = {},
    create = false,
  ) {
    const feature = makeFeature(
      type,
      name,
      sequence,
      undefined,
      parameters,
      create
        ? [occurrence.parentOccurrenceId].filter(Boolean) as string[]
        : [
            occurrence.id,
            ...(occurrence.parentOccurrenceId
              ? [occurrence.parentOccurrenceId]
              : []),
          ],
    );
    feature.componentId = occurrence.componentId;
    feature.occurrenceSnapshot = structuredClone(occurrence);
    feature.outputIds = [occurrence.id];
    return feature;
  }

