    if (!selectedSplitFeature) return;
    const next = cloneProject(project);
    const index = next.features.findIndex(
      (feature) => feature.id === selectedSplitFeature.id,
    );
    if (index < 0) return;
    const feature = next.features[index];
    const before = reconstruct(next.features, index - 1, next.components);
    const source = before.bodies.find((body) =>
      feature.inputIds.includes(body.id),
    );
    if (!source)
      return toast.error("The split source is unavailable at this point in history");
    const stored = feature.parameters as unknown as SplitBodyParameters;
    const workplaneId = patch.workplaneId ?? stored.workplaneId;
    const workplane = [
      ...originWorkplanes(source.componentId),
      ...before.workplanes.map((item) =>
        resolveWorkplane(item, before.bodies),
      ),
    ].find((candidate) => candidate.id === workplaneId);
    if (!workplane) return toast.error("The selected workplane is unavailable");
    const parameters: SplitBodyParameters = {
      ...stored,
      ...patch,
      workplaneId,
      plane: workplane.plane,
      origin: structuredClone(workplane.origin),
      normal: workplane.normal,
      normalVector: workplaneNormalVector(workplane),
    };
    feature.parameters = parameters as unknown as Record<string, unknown>;
    try {
      feature.bodySnapshots = splitBodySnapshots(
        source,
        parameters,
        feature.bodySnapshots ?? [],
      );
    } catch (error) {
      return toast.error(
        error instanceof Error ? error.message : "The body cannot be split.",
      );
    }
    feature.outputIds = feature.bodySnapshots.map((body) => body.id);
    feature.updatedAt = new Date().toISOString();
    commitProject(next);
    setSelectedIds(feature.outputIds);
    setSelectedFeatureId(feature.id);
    setReconstructing(true);
    window.setTimeout(() => setReconstructing(false), 420);
    toast("Split Body updated; downstream history rebuilt");
