  function createEdgeFinish() {
    const edges = currentTopologySelections.filter(
      (selection): selection is Extract<TopologySelection, { kind: "edge" }> =>
        selection.kind === "edge",
    );
    if (!edges.length || edges.length !== currentTopologySelections.length)
      return toast.error("Select one or more body edges only");
    if (new Set(edges.map((edge) => edge.bodyId)).size !== 1)
      return toast.error("Fillet and chamfer edges must belong to one body");
    const source = reconstruction.bodies.find((body) => body.id === edges[0].bodyId);
    if (!source) return toast.error("The source body is unavailable");
    if (edges.some((edge) => edge.ownerId !== source.id))
      return toast.error("Edit edge finishes on the component definition, not an occurrence");
    if (source.locked || project.components.find((component) => component.id === source.componentId)?.locked)
      return toast.error("Unlock the body and its component before finishing edges");
    let parameters: EdgeFinishParameters;
    try {
      parameters = {
        mode: edgeFinishMode,
        distance: edgeFinishDistance,
        segments: Math.round(edgeFinishSegments),
        edges: edges.map((edge) => normalizedEdgeReference(source, edge)),
      };
      const next = cloneProject(project);
      const feature = makeEdgeFinishFeature(
        source,
        parameters,
        next.features.length + 1,
      );
      next.features.push(feature);
      commitProject(next);
      setTopologySelections([]);
      setTopologyMode("body");
      setSelectedIds([source.id]);
      setSelectedFeatureId(feature.id);
      setSelectedComponentId(null);
      toast(`${edgeFinishMode === "fillet" ? "Fillet" : "Chamfer"} added to ${edges.length} edge${edges.length === 1 ? "" : "s"}`);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "The selected edges cannot be finished");
    }
  }

