  function selectedPlanarFace() {
    const face = currentTopologySelections.length === 1
      ? currentTopologySelections[0]
      : null;
    if (!face || face.kind !== "face" || !face.planar || !face.normal)
      return null;
    if (face.ownerId !== face.bodyId) return null;
    const body = reconstruction.bodies.find((item) => item.id === face.bodyId);
    return body ? { face, body } : null;
  }

  function openHoleDialog() {
    const selection = selectedPlanarFace();
    if (!selection) return toast.error("Select exactly one planar body face");
    if (!atEnd) return toast.error("Return to the end of the timeline before adding a hole");
    if (selection.body.locked || project.components.find((component) => component.id === selection.body.componentId)?.locked)
      return toast.error("Unlock the body and its component before adding a hole");
    const size = Math.min(...selection.body.size);
    const diameter = Math.max(0.5, Number((size * 0.2).toFixed(2)));
    const depth = Math.max(1, Number((size * 0.65).toFixed(2)));
    setHoleStyle("simple");
    setHoleExtent("through");
    setHoleDiameter(diameter);
    setHoleDepth(depth);
    setHolePosition([0, 0]);
    setCounterboreDiameter(Number((diameter * 1.7).toFixed(2)));
    setCounterboreDepth(Number((depth * 0.3).toFixed(2)));
    setCountersinkDiameter(Number((diameter * 1.8).toFixed(2)));
    setCountersinkAngle(90);
    setHoleDialogOpen(true);
  }

