    const feature = next.features[index];
    const before = reconstruct(next.features, index - 1, next.components);
    const sketchId = String(feature.parameters.sketchId ?? "");
    const sketch = before.sketches.find((item) => item.id === sketchId);
    if (!sketch) return toast.error("The source sketch is unavailable at this point in history");
    const axisKind = patch.axisKind ?? String(feature.parameters.axisKind ?? "horizontal") as RevolveAxisKind;
    const axisEntityId = axisKind === "construction"
      ? (patch.axisEntityId ?? (feature.parameters.axisEntityId ? String(feature.parameters.axisEntityId) : undefined))
      : undefined;
    const angle = patch.angle ?? Number(feature.parameters.angle ?? 360);
    const entityIds = (feature.parameters.entityIds as string[] | undefined) ?? [];
    let rebuilt: Body;
    try {
      rebuilt = makeRevolutionBody(
        sketch,
        entityIds,
        angle,
        axisKind,
        axisEntityId,
        String(feature.parameters.operation ?? "new") as "new" | "join" | "cut",
        feature.snapshot,
        before.bodies,
      );
    } catch (error) {
      return toast.error(error instanceof Error ? error.message : "Invalid revolve settings");
    }
    feature.snapshot = rebuilt;
    feature.parameters = { ...feature.parameters, angle, axisKind, axisEntityId };
    feature.status = "valid";
    feature.updatedAt = new Date().toISOString();
    next.features.slice(index + 1).forEach((later) => {
      if (later.snapshot?.id !== rebuilt.id) return;
      later.snapshot = { ...later.snapshot, profile: rebuilt.profile, profileHoles: rebuilt.profileHoles, size: rebuilt.size, position: rebuilt.position, revolve: rebuilt.revolve };
    });
