  function duplicateSelection() {
    if (currentTopologySelections.length) {
      toast.error("Faces, edges, and vertices are references; duplicate the parent body instead");
      return;
    }
    if (selectedOccurrence) {
      const copy: ComponentOccurrence = {
        ...structuredClone(selectedOccurrence),
        id: uid("occurrence"),
        name: `${selectedOccurrence.name} copy`,
        position: [
          selectedOccurrence.position[0] + 8,
          selectedOccurrence.position[1] + 8,
          selectedOccurrence.position[2],
        ],
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
      const next = cloneProject(project);
      const feature = occurrenceFeature(
        "Create occurrence",
        `Duplicate ${selectedOccurrence.name}`,
        copy,
        next.features.length + 1,
        { sourceOccurrenceId: selectedOccurrence.id },
        true,
      );
      next.features.push(feature);
      commitProject(next);
      setSelectedIds([copy.id]);
      setSelectedFeatureId(feature.id);
      setSelectedComponentId(null);
      return;
    }
    const body = selectedBody;
    if (!body) return;
    const copy = {
      ...structuredClone(body),
      id: uid("body"),
      name: `${body.name} copy`,
      position: [
        body.position[0] + 8,
        body.position[1] + 8,
        body.position[2],
      ] as Vec3,
    };
    const next = cloneProject(project);
    next.features.push(
      makeFeature(
        "Duplicate",
        `Duplicate ${body.name}`,
        next.features.length + 1,
        copy,
        {},
        [body.id],
      ),
    );
    commitProject(next);
    setSelectedIds([copy.id]);
    setSelectedComponentId(null);
  }

  function deleteSelection() {
    if (currentTopologySelections.length) {
      toast.error("Topology deletion is not a history operation yet; select the parent body to delete it");
      return;
    }
    if (!selectedIds.length) return;
    const dependents = project.features.filter((feature) =>
      feature.inputIds.some((id) => selectedIds.includes(id)),
    ).length;
    if (
      !window.confirm(
        `Delete ${selectedIds.length} selected object${selectedIds.length > 1 ? "s" : ""}? ${dependents ? `${dependents} downstream feature(s) may become unresolved.` : ""}`,
      )
    )
      return;
    const occurrenceIds = selectedIds.filter((id) =>
      project.occurrences.some((occurrence) => occurrence.id === id),
    );
    const bodyIds = selectedIds.filter((id) =>
      reconstruction.bodies.some((body) => body.id === id),
    );
    const workplaneIds = selectedIds.filter((id) =>
      reconstruction.workplanes.some((workplane) => workplane.id === id),
    );
    let next = removeOccurrencesFromProject(project, occurrenceIds);
    next = removeBodiesFromProject(next, bodyIds);
    next = removeWorkplanesFromProject(next, workplaneIds);
    commitProject(next);
    if (
      isolatedOccurrenceId &&
      occurrenceIds.includes(isolatedOccurrenceId)
    )
      setIsolatedOccurrenceId(null);
    setSelectedIds([]);
    setSelectedFeatureId(null);
    toast(
      `${selectedIds.length} object${selectedIds.length > 1 ? "s" : ""} removed · Undo to restore`,
    );
  }

  function suppressFeature(featureId: string) {
    const next = cloneProject(project);
    const feature = next.features.find((item) => item.id === featureId);
    if (!feature) return;
    feature.suppressed = !feature.suppressed;
    feature.status = feature.suppressed ? "suppressed" : "valid";
    if (
      feature.suppressed &&
      feature.workplaneSnapshot?.id === next.activeWorkplaneId
    )
      next.activeWorkplaneId = ORIGIN_WORKPLANE_ID;
    feature.updatedAt = new Date().toISOString();
    commitProject(next);
  }

  function moveFeatureInHistory(featureId: string, direction: -1 | 1) {
    const index = project.features.findIndex((item) => item.id === featureId);
    const target = index + direction;
    if (!canReorderFeature(project.features, index, target)) {
      toast.error("That move would break a feature dependency");
      return;
    }
    const next = cloneProject(project);
    next.features = reorderFeature(next.features, index, target);
    commitProject(next);
    setSelectedFeatureId(featureId);
  }

