  async function importGeometry(file: File) {
    const extension = file.name.split(".").pop()?.toLowerCase();
    if (!extension || !["stl", "obj", "3mf"].includes(extension))
      return toast.error("Choose an STL, OBJ, or 3MF mesh file");
    importWorkerRef.current?.terminate();
    const worker = new Worker(new URL("../workers/import.worker.ts", import.meta.url), { type: "module" });
    importWorkerRef.current = worker;
    const buffer = await file.arrayBuffer();
    setMeshRepairs({ deduplicate: false, removeDegenerate: false, recalculateNormals: false, flipWinding: false, closeSmallHoles: false });
    setImportProgress({ progress: 0.05, message: "Starting mesh review" });
    worker.onmessage = (event) => {
      if (event.data.type === "progress") {
        setImportProgress({ progress: event.data.progress, message: event.data.message });
        return;
      }
      worker.terminate();
      importWorkerRef.current = null;
      if (event.data.type === "error") {
        setImportProgress(null);
        toast.error(event.data.message);
        return;
      }
      const parsed = event.data.parsed as ParsedMesh;
      setImportReview({
        file,
        buffer: event.data.buffer as ArrayBuffer,
        parsed,
        diagnostics: event.data.diagnostics as MeshDiagnostics,
        sourceUnits: parsed.detectedUnits ?? project.units,
      });
      setImportProgress(null);
    };
    worker.onerror = () => {
      worker.terminate();
      importWorkerRef.current = null;
      setImportProgress(null);
      toast.error("The mesh parser could not review this file");
    };
    worker.postMessage({ requestId: Date.now(), buffer, format: extension.toUpperCase() as MeshFormat }, [buffer]);
  }

  function commitGeometryImport() {
    if (!importReview || !preparedImport) return;
    const prepared = preparedImport;
    const safeDimensions = prepared.baseDimensions.map((value) => Math.max(value, 0.000001)) as Vec3;
    const body = makeBody("Imported mesh", {
      componentId: project.activeComponentId,
      name: importReview.file.name,
      color: "#7d99a1",
      size: safeDimensions,
      position: prepared.center,
      mesh: {
        vertices: prepared.vertices,
        indices: prepared.indices,
        baseDimensions: safeDimensions,
        sourceName: importReview.file.name,
        sourceFormat: prepared.format,
        sourceFileSize: importReview.file.size,
        importUnits: importReview.sourceUnits,
        sourceData: importReview.file.size <= 5_000_000 ? arrayBufferToBase64(importReview.buffer) : undefined,
        sourceMime: importReview.file.type || `model/${prepared.format.toLowerCase()}`,
        diagnostics: prepared.diagnostics,
        repairs: prepared.repairs,
      },
    });
    const next = cloneProject(project);
    const feature = makeFeature(
      "Import geometry",
      `Import ${importReview.file.name}`,
      next.features.length + 1,
      body,
      {
        filename: importReview.file.name,
        fileSize: importReview.file.size,
        format: prepared.format,
        sourceUnits: importReview.sourceUnits,
        projectUnits: project.units,
        sourcePreserved: importReview.file.size <= 5_000_000,
        diagnosticsBefore: importReview.diagnostics,
        diagnosticsAfter: prepared.diagnostics,
        repairs: prepared.repairs,
      },
    );
    feature.status = meshHasSeriousIssues(prepared.diagnostics) ? "warning" : "valid";
    next.features.push(feature);
    commitProject(next);
    setSelectedIds([body.id]);
    setSelectedFeatureId(feature.id);
    setSelectedComponentId(null);
    setImportReview(null);
    toast(`Imported ${prepared.indices.length / 3} triangles as an actual mesh body`);
  }

