  async function exportViewportGeometry(
    format: "stl" | "obj" | "3mf",
    scope: "visible" | "selection",
  ) {
    try {
      const selected = scope === "selection" ? selectedIds : undefined;
      const diagnostics = viewportRef.current?.preflightGeometry(selected);
      if (!diagnostics) throw new Error("The viewport is not ready yet");
      if (meshHasSeriousIssues(diagnostics)) {
        const acknowledged = window.confirm(
          `Fabrication preflight found mesh integrity issues:\n\n` +
          `${diagnostics.boundaryEdges} open edges · ${diagnostics.nonManifoldEdges} non-manifold edges · ${diagnostics.inconsistentWindingEdges} winding conflicts · ${diagnostics.degenerateTriangles} degenerate triangles` +
          `${diagnostics.zeroVolume ? " · zero volume" : ""}${diagnostics.invertedWinding ? " · inverted winding" : ""}\n\nExport deliberately anyway?`,
        );
        if (!acknowledged) return;
      }
      const result = await viewportRef.current?.exportGeometry(
        format,
        selected,
        project.units,
      );
      if (!result) throw new Error("The viewport is not ready yet");
      downloadBlob(
        result.blob,
        `${exportBaseName(project.name)}-${scope}.${format}`,
      );
      toast(
        `${format.toUpperCase()} exported · ${result.objectCount} ${result.objectCount === 1 ? "object" : "objects"} · ${project.units}`,
      );
    } catch (error) {
      toast.error(
        error instanceof Error ? error.message : "The model could not be exported",
      );
    }
  }

