import type {
  DimensionType,
  Sketch,
  SketchConstraint,
  SketchEntity,
  Vec2,
} from "@/lib/benchcad-model";

const EPSILON = 1e-7;

export interface SketchIssue {
  code: string;
  severity: "error" | "warning";
  message: string;
  entityIds: string[];
  relationId?: string;
}

export interface SketchProfileDiagnostic {
  entityId: string;
  valid: boolean;
  area: number;
  message: string;
}

export interface SketchAnalysis {
  solveState: "OVER-CONSTRAINED" | "FULLY CONSTRAINED" | "UNDER-CONSTRAINED" | "INVALID GEOMETRY";
  remainingDof: number;
  entityDof: Record<string, number>;
  issues: SketchIssue[];
  profiles: SketchProfileDiagnostic[];
  validProfileIds: string[];
  brokenProjectionIds: string[];
  canFinish: boolean;
}

export interface ProfileSelectionAnalysis {
  ready: boolean;
  message: string;
  orderedIds: string[];
  outerId?: string;
  holeIds: string[];
}

const distance = (first: Vec2, second: Vec2) =>
  Math.hypot(first[0] - second[0], first[1] - second[1]);
const rounded = (value: number) => Number(value.toFixed(8));

export function sketchEntityDof(entity: SketchEntity) {
  if (entity.fixed || entity.projection?.linked) return 0;
  if (entity.kind === "point") return 2;
  if (entity.kind === "rectangle") return 4;
  if (entity.kind === "circle") return 3;
  if (entity.kind === "arc") return 5;
  return entity.points.length * 2;
}

export function sketchProfilePoints(entity: SketchEntity): Vec2[] {
  if (entity.construction) return [];
  if (entity.kind === "rectangle")
    return [
      [entity.x, entity.y],
      [entity.x + entity.width, entity.y],
      [entity.x + entity.width, entity.y + entity.height],
      [entity.x, entity.y + entity.height],
    ];
  if (entity.kind === "circle")
    return Array.from({ length: 64 }, (_, index) => {
      const angle = (index / 64) * Math.PI * 2;
      return [
        entity.x + Math.cos(angle) * entity.radius,
        entity.y + Math.sin(angle) * entity.radius,
      ] as Vec2;
    });
  if (entity.kind === "polyline" && entity.closed) return entity.points;
  return [];
}

export function sketchProfileArea(points: Vec2[]) {
  if (points.length < 3) return 0;
  return Math.abs(
    points.reduce((sum, point, index) => {
      const next = points[(index + 1) % points.length];
      return sum + point[0] * next[1] - next[0] * point[1];
    }, 0) / 2,
  );
}

function orientation(first: Vec2, second: Vec2, third: Vec2) {
  return (
    (second[0] - first[0]) * (third[1] - first[1]) -
    (second[1] - first[1]) * (third[0] - first[0])
  );
}

function onSegment(first: Vec2, point: Vec2, second: Vec2) {
  return (
    Math.abs(orientation(first, point, second)) <= EPSILON &&
    point[0] >= Math.min(first[0], second[0]) - EPSILON &&
    point[0] <= Math.max(first[0], second[0]) + EPSILON &&
    point[1] >= Math.min(first[1], second[1]) - EPSILON &&
    point[1] <= Math.max(first[1], second[1]) + EPSILON
  );
}

function segmentsIntersect(a: Vec2, b: Vec2, c: Vec2, d: Vec2) {
  const first = orientation(a, b, c);
  const second = orientation(a, b, d);
  const third = orientation(c, d, a);
  const fourth = orientation(c, d, b);
  if (
    ((first > EPSILON && second < -EPSILON) || (first < -EPSILON && second > EPSILON)) &&
    ((third > EPSILON && fourth < -EPSILON) || (third < -EPSILON && fourth > EPSILON))
  )
    return true;
  return (
    onSegment(a, c, b) ||
    onSegment(a, d, b) ||
    onSegment(c, a, d) ||
    onSegment(c, b, d)
  );
}

function polygonSelfIntersects(points: Vec2[]) {
  for (let first = 0; first < points.length; first += 1) {
    const firstNext = (first + 1) % points.length;
    for (let second = first + 1; second < points.length; second += 1) {
      const secondNext = (second + 1) % points.length;
      if (
        first === second ||
        firstNext === second ||
        secondNext === first ||
        (first === 0 && secondNext === 0)
      )
        continue;
      if (segmentsIntersect(points[first], points[firstNext], points[second], points[secondNext]))
        return true;
    }
  }
  return false;
}

function polygonsIntersect(first: Vec2[], second: Vec2[]) {
  return first.some((point, index) =>
    second.some((other, otherIndex) =>
      segmentsIntersect(
        point,
        first[(index + 1) % first.length],
        other,
        second[(otherIndex + 1) % second.length],
      ),
    ),
  );
}

function pointInPolygon(point: Vec2, polygon: Vec2[]) {
  let inside = false;
  for (let index = 0, previous = polygon.length - 1; index < polygon.length; previous = index++) {
    const current = polygon[index];
    const prior = polygon[previous];
    if (onSegment(prior, point, current)) return true;
    if (
      current[1] > point[1] !== prior[1] > point[1] &&
      point[0] <
        ((prior[0] - current[0]) * (point[1] - current[1])) /
          (prior[1] - current[1]) +
          current[0]
    )
      inside = !inside;
  }
  return inside;
}

function entityIsFinite(entity: SketchEntity) {
  if (entity.kind === "polyline")
    return entity.points.every((point) => point.every(Number.isFinite));
  return Object.entries(entity).every(
    ([key, value]) =>
      !["x", "y", "width", "height", "radius", "startAngle", "endAngle"].includes(key) ||
      (typeof value === "number" && Number.isFinite(value)),
  );
}

function constraintWeight(constraint: SketchConstraint) {
  if (constraint.type === "fixed") return Number.POSITIVE_INFINITY;
  if (["coincident", "concentric", "symmetric"].includes(constraint.type)) return 2;
  return 1;
}

export function analyzeSketch(sketch: Sketch, bodyIds: string[] = []): SketchAnalysis {
  const issues: SketchIssue[] = [];
  const bodyIdSet = new Set(bodyIds);
  const entityById = new Map(sketch.entities.map((entity) => [entity.id, entity]));
  const brokenProjectionIds: string[] = [];

  sketch.entities.forEach((entity) => {
    if (!entityIsFinite(entity))
      issues.push({
        code: "NON_FINITE_GEOMETRY",
        severity: "error",
        message: "Geometry contains a non-finite coordinate.",
        entityIds: [entity.id],
      });
    if (entity.kind === "rectangle" && (entity.width <= EPSILON || entity.height <= EPSILON))
      issues.push({
        code: "DEGENERATE_RECTANGLE",
        severity: "error",
        message: "Rectangle width and height must be greater than zero.",
        entityIds: [entity.id],
      });
    if ((entity.kind === "circle" || entity.kind === "arc") && entity.radius <= EPSILON)
      issues.push({
        code: "DEGENERATE_RADIUS",
        severity: "error",
        message: "Circle and arc radius must be greater than zero.",
        entityIds: [entity.id],
      });
    if (entity.kind === "polyline") {
      if (entity.points.length < (entity.closed ? 3 : 2))
        issues.push({
          code: "TOO_FEW_VERTICES",
          severity: "error",
          message: entity.closed
            ? "A closed profile needs at least three vertices."
            : "An open chain needs at least two vertices.",
          entityIds: [entity.id],
        });
      const segmentCount = entity.closed
        ? entity.points.length
        : Math.max(0, entity.points.length - 1);
      if (entity.points.slice(0, segmentCount).some((point, index) => distance(point, entity.points[(index + 1) % entity.points.length]) <= EPSILON))
        issues.push({
          code: "ZERO_LENGTH_SEGMENT",
          severity: "error",
          message: "Polyline contains a zero-length segment.",
          entityIds: [entity.id],
        });
    }
    if (entity.projection?.linked && bodyIds.length && !bodyIdSet.has(entity.projection.bodyId)) {
      brokenProjectionIds.push(entity.id);
      issues.push({
        code: "BROKEN_PROJECTION",
        severity: "warning",
        message: "Linked projection source is unavailable; the last valid geometry is preserved.",
        entityIds: [entity.id],
      });
    }
  });

  const relations = [...(sketch.constraints ?? []), ...(sketch.dimensions ?? [])];
  relations.forEach((relation) => {
    const missing = relation.entityIds.filter((id) => !entityById.has(id));
    if (missing.length)
      issues.push({
        code: "ORPHAN_RELATION",
        severity: "error",
        message: `${relation.type} references deleted geometry.`,
        entityIds: missing,
        relationId: relation.id,
      });
    if (relation.status === "conflict")
      issues.push({
        code: "RELATION_CONFLICT",
        severity: "error",
        message: relation.message ?? `${relation.type} cannot be satisfied.`,
        entityIds: relation.entityIds,
        relationId: relation.id,
      });
  });

  const dimensionKeys = new Map<string, string>();
  (sketch.dimensions ?? [])
    .filter((dimension) => dimension.driving && dimension.status === "valid")
    .forEach((dimension) => {
      const key = `${dimension.type}:${[...dimension.entityIds].sort().join(":")}`;
      const existing = dimensionKeys.get(key);
      if (existing)
        issues.push({
          code: "DUPLICATE_DRIVING_DIMENSION",
          severity: "error",
          message: `${dimension.type} already has a driving dimension on this geometry.`,
          entityIds: dimension.entityIds,
          relationId: dimension.id,
        });
      else dimensionKeys.set(key, dimension.id);
    });

  const profiles: SketchProfileDiagnostic[] = sketch.entities
    .map((entity) => {
      const points = sketchProfilePoints(entity);
      if (!points.length) return null;
      const area = sketchProfileArea(points);
      let message = "Profile is ready for a solid feature.";
      let valid = area > EPSILON;
      if (entity.kind === "polyline" && polygonSelfIntersects(points)) {
        valid = false;
        message = "Profile crosses itself.";
        issues.push({
          code: "SELF_INTERSECTING_PROFILE",
          severity: "error",
          message,
          entityIds: [entity.id],
        });
      } else if (!valid) {
        message = "Profile has zero enclosed area.";
        issues.push({
          code: "ZERO_AREA_PROFILE",
          severity: "error",
          message,
          entityIds: [entity.id],
        });
      }
      else if (brokenProjectionIds.includes(entity.id)) {
        valid = false;
        message = "Profile depends on a missing projected source.";
      } else if (issues.some((issue) => issue.severity === "error" && issue.entityIds.includes(entity.id))) {
        valid = false;
        message = "Profile contains invalid geometry or relations.";
      }
      return { entityId: entity.id, valid, area, message };
    })
    .filter((profile): profile is SketchProfileDiagnostic => Boolean(profile));

  const entityDof = Object.fromEntries(
    sketch.entities.map((entity) => [entity.id, sketchEntityDof(entity)]),
  );
  (sketch.constraints ?? [])
    .filter((constraint) => constraint.status === "valid")
    .forEach((constraint) => {
      const weight = constraintWeight(constraint);
      constraint.entityIds.forEach((id) => {
        if (!(id in entityDof)) return;
        entityDof[id] = Number.isFinite(weight)
          ? Math.max(0, entityDof[id] - Math.ceil(weight / constraint.entityIds.length))
          : 0;
      });
    });
  (sketch.dimensions ?? [])
    .filter((dimension) => dimension.status === "valid")
    .forEach((dimension) =>
      dimension.entityIds.forEach((id) => {
        if (id in entityDof) entityDof[id] = Math.max(0, entityDof[id] - 1);
      }),
    );
  const baseDof = sketch.entities.reduce((sum, entity) => sum + sketchEntityDof(entity), 0);
  const relationReduction = (sketch.constraints ?? [])
    .filter((constraint) => constraint.status === "valid")
    .reduce((sum, constraint) => {
      const weight = constraintWeight(constraint);
      return sum +
        (Number.isFinite(weight)
          ? weight
          : constraint.entityIds.reduce((total, id) => {
              const entity = entityById.get(id);
              return total + (entity ? sketchEntityDof(entity) : 0);
            }, 0));
    }, 0);
  const dimensionReduction = (sketch.dimensions ?? []).filter(
    (dimension) => dimension.status === "valid",
  ).length;
  const remainingDof = Math.max(0, baseDof - relationReduction - dimensionReduction);
  const errorIssues = issues.filter((issue) => issue.severity === "error");
  const invalidGeometry = errorIssues.some((issue) =>
    ["NON_FINITE_GEOMETRY", "DEGENERATE_RECTANGLE", "DEGENERATE_RADIUS", "TOO_FEW_VERTICES", "ZERO_LENGTH_SEGMENT", "SELF_INTERSECTING_PROFILE", "ZERO_AREA_PROFILE"].includes(issue.code),
  );
  const solveState = invalidGeometry
    ? "INVALID GEOMETRY"
    : errorIssues.length
      ? "OVER-CONSTRAINED"
      : remainingDof === 0 && sketch.entities.length
        ? "FULLY CONSTRAINED"
        : "UNDER-CONSTRAINED";
  return {
    solveState,
    remainingDof,
    entityDof,
    issues,
    profiles,
    validProfileIds: profiles.filter((profile) => profile.valid).map((profile) => profile.entityId),
    brokenProjectionIds,
    canFinish: errorIssues.length === 0,
  };
}

export function analyzeProfileSelection(
  sketch: Sketch,
  entityIds: string[],
  analysis = analyzeSketch(sketch),
): ProfileSelectionAnalysis {
  const selected = entityIds
    .map((id) => ({
      id,
      entity: sketch.entities.find((entity) => entity.id === id),
      diagnostic: analysis.profiles.find((profile) => profile.entityId === id),
    }))
    .filter((item) => item.entity);
  if (!selected.length)
    return { ready: false, message: "Select one or more closed profiles.", orderedIds: [], holeIds: [] };
  const invalid = selected.find((item) => !item.diagnostic?.valid);
  if (invalid)
    return {
      ready: false,
      message: invalid.diagnostic?.message ?? "Selection contains open or invalid geometry.",
      orderedIds: [],
      holeIds: [],
    };
  const ordered = selected
    .map((item) => ({ ...item, points: sketchProfilePoints(item.entity!) }))
    .sort((first, second) => second.diagnostic!.area - first.diagnostic!.area);
  const outer = ordered[0];
  for (const inner of ordered.slice(1)) {
    if (polygonsIntersect(outer.points, inner.points))
      return {
        ready: false,
        message: "Selected profile boundaries intersect or touch.",
        orderedIds: [],
        holeIds: [],
      };
    if (!inner.points.every((point) => pointInPolygon(point, outer.points)))
      return {
        ready: false,
        message: "Select one outer profile and only profiles fully contained inside it as holes.",
        orderedIds: [],
        holeIds: [],
      };
  }
  for (let first = 1; first < ordered.length; first += 1)
    for (let second = first + 1; second < ordered.length; second += 1)
      if (
        polygonsIntersect(ordered[first].points, ordered[second].points) ||
        ordered[second].points.some((point) => pointInPolygon(point, ordered[first].points)) ||
        ordered[first].points.some((point) => pointInPolygon(point, ordered[second].points))
      )
        return {
          ready: false,
          message: "Nested or overlapping holes are not supported in one solid profile.",
          orderedIds: [],
          holeIds: [],
        };
  return {
    ready: true,
    message:
      ordered.length === 1
        ? "One valid outer profile is ready."
        : `One outer profile and ${ordered.length - 1} contained hole${ordered.length === 2 ? "" : "s"} are ready.`,
    outerId: outer.id,
    holeIds: ordered.slice(1).map((item) => item.id),
    orderedIds: ordered.map((item) => item.id),
  };
}

function lineSegment(entity: SketchEntity): [Vec2, Vec2] | null {
  return entity.kind === "polyline" && entity.points.length >= 2
    ? [entity.points[0], entity.points[1]]
    : null;
}

function entityCenter(entity: SketchEntity): Vec2 {
  if (entity.kind === "rectangle")
    return [entity.x + entity.width / 2, entity.y + entity.height / 2];
  if (entity.kind === "circle" || entity.kind === "arc" || entity.kind === "point")
    return [entity.x, entity.y];
  return [
    entity.points.reduce((sum, point) => sum + point[0], 0) / entity.points.length,
    entity.points.reduce((sum, point) => sum + point[1], 0) / entity.points.length,
  ];
}

function translateEntity(entity: SketchEntity, delta: Vec2) {
  if (entity.kind === "polyline")
    entity.points = entity.points.map(([x, y]) => [rounded(x + delta[0]), rounded(y + delta[1])]);
  else {
    entity.x = rounded(entity.x + delta[0]);
    entity.y = rounded(entity.y + delta[1]);
  }
}

function applyDimension(entity: SketchEntity, type: DimensionType, value: number) {
  if (!Number.isFinite(value) || value <= 0) return false;
  const pair = lineSegment(entity);
  if (type === "horizontal") {
    if (entity.kind === "rectangle") entity.width = value;
    else if (pair && entity.kind === "polyline")
      entity.points[1][0] = rounded(entity.points[0][0] + Math.sign(pair[1][0] - pair[0][0] || 1) * value);
    else return false;
  } else if (type === "vertical") {
    if (entity.kind === "rectangle") entity.height = value;
    else if (pair && entity.kind === "polyline")
      entity.points[1][1] = rounded(entity.points[0][1] + Math.sign(pair[1][1] - pair[0][1] || 1) * value);
    else return false;
  } else if (type === "radial" || type === "diameter") {
    if (entity.kind !== "circle" && entity.kind !== "arc") return false;
    entity.radius = type === "diameter" ? value / 2 : value;
  } else {
    if (!pair || entity.kind !== "polyline") return false;
    const length = distance(pair[0], pair[1]);
    entity.points[1] = [
      rounded(pair[0][0] + Math.cos((value * Math.PI) / 180) * length),
      rounded(pair[0][1] + Math.sin((value * Math.PI) / 180) * length),
    ];
  }
  return true;
}

export function resolveSketchRelations(sketch: Sketch): Sketch {
  const next = structuredClone(sketch);
  const byId = new Map(next.entities.map((entity) => [entity.id, entity]));
  for (let pass = 0; pass < 2; pass += 1) {
    (next.constraints ?? [])
      .filter((constraint) => constraint.status === "valid")
      .forEach((constraint) => {
        const chosen = constraint.entityIds.map((id) => byId.get(id)).filter((entity): entity is SketchEntity => Boolean(entity));
        if (!chosen.length || constraint.type === "fixed") return;
        if (constraint.type === "horizontal" || constraint.type === "vertical") {
          const line = chosen[0];
          if (line.kind !== "polyline" || line.points.length < 2) return;
          if (constraint.type === "horizontal") line.points[1][1] = line.points[0][1];
          else line.points[1][0] = line.points[0][0];
        } else if (constraint.type === "coincident" && chosen.length >= 2) {
          const first = chosen[0];
          const second = chosen[1];
          if (first.kind === "polyline" && second.kind === "polyline")
            second.points[0] = [...first.points.at(-1)!] as Vec2;
          else {
            const target = entityCenter(first);
            const current = entityCenter(second);
            translateEntity(second, [target[0] - current[0], target[1] - current[1]]);
          }
        } else if (
          (constraint.type === "parallel" || constraint.type === "perpendicular") &&
          chosen.length >= 2
        ) {
          const firstLine = lineSegment(chosen[0]);
          const secondLine = lineSegment(chosen[1]);
          if (!firstLine || !secondLine || chosen[1].kind !== "polyline") return;
          const angle =
            Math.atan2(firstLine[1][1] - firstLine[0][1], firstLine[1][0] - firstLine[0][0]) +
            (constraint.type === "perpendicular" ? Math.PI / 2 : 0);
          const length = distance(secondLine[0], secondLine[1]);
          chosen[1].points[1] = [
            rounded(secondLine[0][0] + Math.cos(angle) * length),
            rounded(secondLine[0][1] + Math.sin(angle) * length),
          ];
        } else if (constraint.type === "concentric" && chosen.length >= 2) {
          const first = chosen[0];
          const second = chosen[1];
          if (
            (first.kind === "circle" || first.kind === "arc") &&
            (second.kind === "circle" || second.kind === "arc")
          ) {
            second.x = first.x;
            second.y = first.y;
          }
        } else if (constraint.type === "equal" && chosen.length >= 2) {
          const first = chosen[0];
          const second = chosen[1];
          if (
            (first.kind === "circle" || first.kind === "arc") &&
            (second.kind === "circle" || second.kind === "arc")
          )
            second.radius = first.radius;
          else if (first.kind === "rectangle" && second.kind === "rectangle") {
            second.width = first.width;
            second.height = first.height;
          } else {
            const firstLine = lineSegment(first);
            const secondLine = lineSegment(second);
            if (firstLine && secondLine && second.kind === "polyline") {
              const angle = Math.atan2(secondLine[1][1] - secondLine[0][1], secondLine[1][0] - secondLine[0][0]);
              const length = distance(firstLine[0], firstLine[1]);
              second.points[1] = [
                rounded(secondLine[0][0] + Math.cos(angle) * length),
                rounded(secondLine[0][1] + Math.sin(angle) * length),
              ];
            }
          }
        } else if (constraint.type === "symmetric" && chosen.length >= 2) {
          const firstCenter = entityCenter(chosen[0]);
          const secondCenter = entityCenter(chosen[1]);
          const midpoint: Vec2 = [
            (firstCenter[0] + secondCenter[0]) / 2,
            (firstCenter[1] + secondCenter[1]) / 2,
          ];
          translateEntity(chosen[0], [-midpoint[0], -midpoint[1]]);
          translateEntity(chosen[1], [-midpoint[0], -midpoint[1]]);
        } else if (constraint.type === "tangent" && chosen.length >= 2) {
          const line = chosen.find((entity) => lineSegment(entity));
          const curve = chosen.find(
            (entity) => entity.kind === "circle" || entity.kind === "arc",
          );
          const pair = line ? lineSegment(line) : null;
          if (!pair || !curve || (curve.kind !== "circle" && curve.kind !== "arc")) return;
          const length = distance(pair[0], pair[1]) || 1;
          curve.x = rounded(pair[0][0] - ((pair[1][1] - pair[0][1]) / length) * curve.radius);
          curve.y = rounded(pair[0][1] + ((pair[1][0] - pair[0][0]) / length) * curve.radius);
        }
      });
    (next.dimensions ?? [])
      .filter((dimension) => dimension.status === "valid" && dimension.driving)
      .forEach((dimension) => {
        const entity = byId.get(dimension.entityIds[0]);
        if (entity) applyDimension(entity, dimension.type, dimension.value);
      });
  }
  return next;
}

export function updateDrivingDimension(sketch: Sketch, dimensionId: string, value: number) {
  const next = structuredClone(sketch);
  const dimension = (next.dimensions ?? []).find((item) => item.id === dimensionId);
  if (!dimension || !Number.isFinite(value) || value <= 0) return sketch;
  dimension.value = value;
  dimension.status = "valid";
  dimension.message = "Driving dimension solved.";
  return resolveSketchRelations(next);
}

export function pruneSketchRelations(sketch: Sketch, removedEntityIds: string[]) {
  const removed = new Set(removedEntityIds);
  return {
    ...sketch,
    constraints: (sketch.constraints ?? []).filter((relation) =>
      relation.entityIds.every((id) => !removed.has(id)),
    ),
    dimensions: (sketch.dimensions ?? []).filter((dimension) =>
      dimension.entityIds.every((id) => !removed.has(id)),
    ),
  };
}
