import type { BenchProject, Sketch, SketchEntity, Vec2 } from "./benchcad-model";

export type ExportUnit = BenchProject["units"];

export interface ExportMeshData {
  name: string;
  vertices: number[];
  triangles: number[];
  bodyId?: string;
  color?: string;
}

const number = (value: number) => Number(value.toFixed(5)).toString();

const xml = (value: string) =>
  value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");

export function exportBaseName(value: string) {
  return (
    value
      .trim()
      .replace(/[^a-z0-9._-]+/gi, "-")
      .replace(/^-+|-+$/g, "")
      .toLowerCase() || "benchcad-model"
  );
}

function svgUnit(units: ExportUnit) {
  return units === "in" ? "in" : units;
}

function pointsForBounds(entity: SketchEntity): Vec2[] {
  if (entity.kind === "rectangle")
    return [
      [entity.x, entity.y],
      [entity.x + entity.width, entity.y + entity.height],
    ];
  if (entity.kind === "circle")
    return [
      [entity.x - entity.radius, entity.y - entity.radius],
      [entity.x + entity.radius, entity.y + entity.radius],
    ];
  if (entity.kind === "point") return [[entity.x, entity.y]];
  if (entity.kind === "polyline") return entity.points;
  const span = entity.endAngle - entity.startAngle;
  const samples = Math.max(8, Math.ceil(Math.abs(span) / (Math.PI / 12)));
  return Array.from({ length: samples + 1 }, (_, index) => {
    const angle = entity.startAngle + (span * index) / samples;
    return [
      entity.x + Math.cos(angle) * entity.radius,
      entity.y + Math.sin(angle) * entity.radius,
    ];
  });
}

function bounds(points: Vec2[]) {
  const safe = points.length ? points : ([[0, 0], [10, 10]] as Vec2[]);
  const xs = safe.map(([x]) => x);
  const ys = safe.map(([, y]) => y);
  return {
    minX: Math.min(...xs),
    maxX: Math.max(...xs),
    minY: Math.min(...ys),
    maxY: Math.max(...ys),
  };
}

function svgDocument(
  name: string,
  units: ExportUnit,
  source: string,
  geometry: string,
  geometryPoints: Vec2[],
) {
  const box = bounds(geometryPoints);
  const span = Math.max(box.maxX - box.minX, box.maxY - box.minY, 1);
  const pad = span * 0.04;
  const minX = box.minX - pad;
  const minY = -box.maxY - pad;
  const width = box.maxX - box.minX + pad * 2;
  const height = box.maxY - box.minY + pad * 2;
  const stroke = Math.max(span / 700, 0.02);
  const unit = svgUnit(units);
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${number(minX)} ${number(minY)} ${number(width)} ${number(height)}" width="${number(width)}${unit}" height="${number(height)}${unit}">`,
    `  <title>${xml(name)}</title>`,
    `  <metadata>BENCHCAD ${xml(source)} · units: ${xml(units)}</metadata>`,
    `  <g fill="none" stroke="#000000" stroke-width="${number(stroke)}" vector-effect="non-scaling-stroke">`,
    geometry,
    "  </g>",
    "</svg>",
  ].join("\n");
}

function point([x, y]: Vec2) {
  return `${number(x)} ${number(-y)}`;
}

function entitySvg(entity: SketchEntity) {
  const attributes = `data-entity-id="${xml(entity.id)}"${entity.projected ? ' data-projected="true"' : ""}`;
  if (entity.kind === "rectangle")
    return `    <rect ${attributes} x="${number(entity.x)}" y="${number(-(entity.y + entity.height))}" width="${number(entity.width)}" height="${number(entity.height)}" />`;
  if (entity.kind === "circle")
    return `    <circle ${attributes} cx="${number(entity.x)}" cy="${number(-entity.y)}" r="${number(entity.radius)}" />`;
  if (entity.kind === "point") {
    const radius = 0.2;
    return `    <circle ${attributes} cx="${number(entity.x)}" cy="${number(-entity.y)}" r="${number(radius)}" />`;
  }
  if (entity.kind === "polyline") {
    if (!entity.points.length) return "";
    const commands = entity.points
      .map((item, index) => `${index ? "L" : "M"} ${point(item)}`)
      .join(" ");
    return `    <path ${attributes} d="${commands}${entity.closed ? " Z" : ""}" />`;
  }
  const start: Vec2 = [
    entity.x + Math.cos(entity.startAngle) * entity.radius,
    entity.y + Math.sin(entity.startAngle) * entity.radius,
  ];
  const end: Vec2 = [
    entity.x + Math.cos(entity.endAngle) * entity.radius,
    entity.y + Math.sin(entity.endAngle) * entity.radius,
  ];
  const span = entity.endAngle - entity.startAngle;
  const largeArc = Math.abs(span) > Math.PI ? 1 : 0;
  const sweep = span >= 0 ? 0 : 1;
  return `    <path ${attributes} d="M ${point(start)} A ${number(entity.radius)} ${number(entity.radius)} 0 ${largeArc} ${sweep} ${point(end)}" />`;
}

export function sketchToSvg(sketch: Sketch, units: ExportUnit) {
  const entities = sketch.entities.filter((entity) => !entity.construction);
  const geometry = entities.map(entitySvg).filter(Boolean).join("\n");
  const geometryPoints = entities.flatMap(pointsForBounds);
  return svgDocument(sketch.name, units, "sketch", geometry, geometryPoints);
}

function contourPath(points: Vec2[]) {
  if (!points.length) return "";
  return `${points.map((item, index) => `${index ? "L" : "M"} ${point(item)}`).join(" ")} Z`;
}

export function profileToSvg(
  name: string,
  profile: Vec2[],
  holes: Vec2[][],
  units: ExportUnit,
) {
  const contours = [profile, ...holes].filter((contour) => contour.length);
  const path = contours.map(contourPath).join(" ");
  const geometry = `    <path data-profile="true" fill-rule="evenodd" d="${path}" />`;
  return svgDocument(
    name,
    units,
    "extrusion profile",
    geometry,
    contours.flat(),
  );
}

function threeMfUnit(units: ExportUnit) {
  if (units === "mm") return "millimeter";
  if (units === "cm") return "centimeter";
  if (units === "in") return "inch";
  return "meter";
}

export function meshesToThreeMfXml(
  meshes: ExportMeshData[],
  units: ExportUnit,
) {
  const displayColor = (value?: string) =>
    /^#[0-9a-f]{6}$/i.test(value ?? "")
      ? `${value!.toUpperCase()}FF`
      : "#E59B42FF";
  const materials = meshes
    .map(
      (mesh) =>
        `      <base name="${xml(mesh.name)}" displaycolor="${displayColor(mesh.color)}" />`,
    )
    .join("\n");
  const objects = meshes
    .map((mesh, meshIndex) => {
      const vertices = Array.from(
        { length: Math.floor(mesh.vertices.length / 3) },
        (_, index) => {
          const offset = index * 3;
          return `          <vertex x="${number(mesh.vertices[offset])}" y="${number(mesh.vertices[offset + 1])}" z="${number(mesh.vertices[offset + 2])}" />`;
        },
      ).join("\n");
      const triangles = Array.from(
        { length: Math.floor(mesh.triangles.length / 3) },
        (_, index) => {
          const offset = index * 3;
          return `          <triangle v1="${mesh.triangles[offset]}" v2="${mesh.triangles[offset + 1]}" v3="${mesh.triangles[offset + 2]}" />`;
        },
      ).join("\n");
      return [
        `      <object id="${meshIndex + 1}" type="model" name="${xml(mesh.name)}" pid="1" pindex="${meshIndex}">`,
        "        <mesh>",
        "        <vertices>",
        vertices,
        "        </vertices>",
        "        <triangles>",
        triangles,
        "        </triangles>",
        "        </mesh>",
        "      </object>",
      ].join("\n");
    })
    .join("\n");
  const build = meshes
    .map((_, index) => `      <item objectid="${index + 1}" />`)
    .join("\n");
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    `<model unit="${threeMfUnit(units)}" xml:lang="en-US" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02">`,
    '  <metadata name="Application">BENCHCAD</metadata>',
    "  <resources>",
    '    <basematerials id="1">',
    materials,
    "    </basematerials>",
    objects,
    "  </resources>",
    "  <build>",
    build,
    "  </build>",
    "</model>",
  ].join("\n");
}
