import {
  makeBody,
  type Body,
  type OrientationFrame,
  type Sketch,
  type SketchEntity,
  type Vec2,
  type Vec3,
} from "./benchcad-model";
import {
  analyzeProfileSelection,
  analyzeSketch,
  sketchProfilePoints,
} from "./benchcad-sketch";

export interface SweepFeatureParameters {
  profileSketchId: string;
  profileEntityIds: string[];
  pathSketchId: string;
  pathEntityId: string;
  twist: number;
  endScale: number;
  operation: "new";
}

export interface LoftFeatureParameters {
  profileSketchIds: [string, string];
  profileEntityIds: [string, string];
  operation: "new";
}

const EPSILON = 1e-8;
const add = (a: Vec3, b: Vec3): Vec3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const subtract = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const scale = (value: Vec3, factor: number): Vec3 => [value[0] * factor, value[1] * factor, value[2] * factor];
const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec3, b: Vec3): Vec3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
const length = (value: Vec3) => Math.hypot(...value);
const normalize = (value: Vec3): Vec3 => {
  const magnitude = length(value);
  if (magnitude <= EPSILON) throw new Error("A sweep or loft direction has zero length.");
  return scale(value, 1 / magnitude);
};

export function sketchBasis(sketch: Sketch): OrientationFrame {
  if (sketch.frame)
    return {
      xAxis: [...sketch.frame.xAxis],
      yAxis: [...sketch.frame.yAxis],
      normal: [...sketch.frame.normal],
    };
  if (sketch.plane === "XY")
    return { xAxis: [1, 0, 0], yAxis: [0, 1, 0], normal: [0, 0, sketch.normal ?? 1] };
  if (sketch.plane === "XZ")
    return { xAxis: [1, 0, 0], yAxis: [0, 0, 1], normal: [0, sketch.normal ?? 1, 0] };
  return { xAxis: [0, 1, 0], yAxis: [0, 0, 1], normal: [sketch.normal ?? 1, 0, 0] };
}

export function sketchPointToWorld(sketch: Sketch, point: Vec2): Vec3 {
  const basis = sketchBasis(sketch);
  const origin = sketch.frame?.origin ?? sketch.origin ?? [0, 0, 0];
  return add(origin, add(scale(basis.xAxis, point[0]), scale(basis.yAxis, point[1])));
}

export function sweepPathEntities(sketch: Sketch) {
  return sketch.entities.filter((entity) =>
    (entity.kind === "polyline" && !entity.closed && entity.points.length >= 2) ||
    entity.kind === "arc",
  );
}

export function pathEntityPoints(sketch: Sketch, entity: SketchEntity): Vec3[] {
  let points: Vec2[];
  if (entity.kind === "polyline" && !entity.closed) points = entity.points;
  else if (entity.kind === "arc") {
    let sweep = entity.endAngle - entity.startAngle;
    while (sweep <= 0) sweep += Math.PI * 2;
    const steps = Math.max(8, Math.ceil((sweep / (Math.PI * 2)) * 48));
    points = Array.from({ length: steps + 1 }, (_, index) => {
      const angle = entity.startAngle + (sweep * index) / steps;
      return [
        entity.x + Math.cos(angle) * entity.radius,
        entity.y + Math.sin(angle) * entity.radius,
      ];
    });
  } else throw new Error("Select one open line, polyline, or arc as the sweep path.");
  const world = points.map((point) => sketchPointToWorld(sketch, point));
  return world.filter(
    (point, index) => index === 0 || length(subtract(point, world[index - 1])) > EPSILON,
  );
}

function sweepFrames(path: Vec3[], preferredX: Vec3, preferredY: Vec3) {
  const tangents = path.map((point, index) => {
    const before = path[Math.max(0, index - 1)];
    const after = path[Math.min(path.length - 1, index + 1)];
    return normalize(subtract(after, before));
  });
  const frames: OrientationFrame[] = [];
  tangents.forEach((tangent, index) => {
    const candidate = index ? frames[index - 1].xAxis : preferredX;
    let xAxis = subtract(candidate, scale(tangent, dot(candidate, tangent)));
    if (length(xAxis) <= EPSILON)
      xAxis = subtract(preferredY, scale(tangent, dot(preferredY, tangent)));
    xAxis = normalize(xAxis);
    let yAxis = normalize(cross(tangent, xAxis));
    if (!index && dot(yAxis, preferredY) < 0) {
      xAxis = scale(xAxis, -1);
      yAxis = scale(yAxis, -1);
    }
    frames.push({ xAxis, yAxis, normal: tangent });
  });
  return frames;
}

function profileSelection(sketch: Sketch, entityIds: string[]) {
  const analysis = analyzeSketch(sketch);
  const selection = analyzeProfileSelection(sketch, entityIds, analysis);
  if (!selection.ready) throw new Error(selection.message);
  return selection.orderedIds.map((id) =>
    sketchProfilePoints(sketch.entities.find((entity) => entity.id === id)!),
  );
}

function boundsCenter(points: Vec3[]) {
  const minimum: Vec3 = [
    Math.min(...points.map((point) => point[0])),
    Math.min(...points.map((point) => point[1])),
    Math.min(...points.map((point) => point[2])),
  ];
  const maximum: Vec3 = [
    Math.max(...points.map((point) => point[0])),
    Math.max(...points.map((point) => point[1])),
    Math.max(...points.map((point) => point[2])),
  ];
  return {
    center: minimum.map((value, axis) => (value + maximum[axis]) / 2) as Vec3,
    size: minimum.map((value, axis) => Math.max(0.001, maximum[axis] - value)) as Vec3,
  };
}

export function buildSweepBody(
  profileSketch: Sketch,
  profileEntityIds: string[],
  pathSketch: Sketch,
  pathEntityId: string,
  twist = 0,
  endScale = 1,
  previous?: Body,
) {
  if (profileSketch.componentId !== pathSketch.componentId)
    throw new Error("Sweep profile and path must belong to the same component.");
  if (!Number.isFinite(twist) || Math.abs(twist) > 1440)
    throw new Error("Sweep twist must be between -1440° and 1440°.");
  if (!Number.isFinite(endScale) || endScale <= 0.01 || endScale > 100)
    throw new Error("Sweep end scale must be greater than 0.01 and no more than 100.");
  const profiles = profileSelection(profileSketch, profileEntityIds);
  const pathEntity = pathSketch.entities.find((entity) => entity.id === pathEntityId);
  if (!pathEntity) throw new Error("The selected sweep path is unavailable.");
  const path = pathEntityPoints(pathSketch, pathEntity);
  if (path.length < 2) throw new Error("Sweep path needs at least two distinct points.");
  const profileBasis = sketchBasis(profileSketch);
  const tangent = normalize(subtract(path[1], path[0]));
  if (Math.abs(dot(profileBasis.normal, tangent)) < 0.7)
    throw new Error("The sweep path must leave the profile approximately normal to its sketch plane.");
  const profileOrigin = sketchPointToWorld(profileSketch, [0, 0]);
  const planeDistance = Math.abs(dot(subtract(path[0], profileOrigin), profileBasis.normal));
  if (planeDistance > 0.01)
    throw new Error("The sweep path must begin on the profile sketch plane.");
  const frames = sweepFrames(path, profileBasis.xAxis, profileBasis.yAxis);
  const toSection = (profile: Vec2[]) =>
    profile.map((point) => {
      const delta = subtract(sketchPointToWorld(profileSketch, point), path[0]);
      return [dot(delta, frames[0].xAxis), dot(delta, frames[0].yAxis)] as Vec2;
    });
  const sections = profiles.map(toSection);
  const envelope = path.flatMap((point, index) => {
    const t = path.length === 1 ? 0 : index / (path.length - 1);
    const factor = 1 + (endScale - 1) * t;
    return sections[0].map(([u, v]) =>
      add(point, add(scale(frames[index].xAxis, u * factor), scale(frames[index].yAxis, v * factor))),
    );
  });
  const bounds = boundsCenter(envelope);
  return makeBody("Sweep", {
    ...previous,
    componentId: previous?.componentId ?? profileSketch.componentId,
    name: previous?.name ?? `${profileSketch.name} sweep`,
    role: previous?.role ?? "solid",
    profile: sections[0],
    profileHoles: sections.slice(1),
    sourceSketchId: profileSketch.id,
    position: bounds.center,
    rotation: previous?.rotation ?? [0, 0, 0],
    size: bounds.size,
    orientation: undefined,
    sweep: {
      path: path.map((point) => subtract(point, bounds.center)),
      xAxes: frames.map((frame) => frame.xAxis),
      yAxes: frames.map((frame) => frame.yAxis),
      twist,
      endScale,
    },
    loft: undefined,
  });
}

function resampleClosedLoop(points: Vec3[], count: number) {
  const lengths = points.map((point, index) =>
    length(subtract(points[(index + 1) % points.length], point)),
  );
  const perimeter = lengths.reduce((sum, value) => sum + value, 0);
  if (perimeter <= EPSILON) throw new Error("Loft profile has zero perimeter.");
  const result: Vec3[] = [];
  let edge = 0;
  let edgeStart = 0;
  for (let index = 0; index < count; index += 1) {
    const target = (perimeter * index) / count;
    while (edge < lengths.length - 1 && edgeStart + lengths[edge] < target) {
      edgeStart += lengths[edge];
      edge += 1;
    }
    const factor = lengths[edge] <= EPSILON ? 0 : (target - edgeStart) / lengths[edge];
    result.push(add(points[edge], scale(subtract(points[(edge + 1) % points.length], points[edge]), factor)));
  }
  return result;
}

function newellNormal(points: Vec3[]) {
  const normal: Vec3 = [0, 0, 0];
  points.forEach((point, index) => {
    const next = points[(index + 1) % points.length];
    normal[0] += (point[1] - next[1]) * (point[2] + next[2]);
    normal[1] += (point[2] - next[2]) * (point[0] + next[0]);
    normal[2] += (point[0] - next[0]) * (point[1] + next[1]);
  });
  return normalize(normal);
}

function convexProfile(points: Vec2[]) {
  let sign = 0;
  for (let index = 0; index < points.length; index += 1) {
    const previous = points[(index + points.length - 1) % points.length];
    const current = points[index];
    const next = points[(index + 1) % points.length];
    const turn =
      (current[0] - previous[0]) * (next[1] - current[1]) -
      (current[1] - previous[1]) * (next[0] - current[0]);
    if (Math.abs(turn) <= 1e-9) continue;
    const currentSign = Math.sign(turn);
    if (sign && currentSign !== sign) return false;
    sign = currentSign;
  }
  return Boolean(sign);
}

function rotateLoop<T>(points: T[], offset: number) {
  return points.map((_, index) => points[(index + offset) % points.length]);
}

function alignLoftLoops(first: Vec3[], second: Vec3[]) {
  let best = second;
  let bestScore = Number.POSITIVE_INFINITY;
  for (let offset = 0; offset < second.length; offset += 1) {
    const candidate = rotateLoop(second, offset);
    const score = first.reduce((sum, point, index) => {
      const delta = subtract(point, candidate[index]);
      return sum + dot(delta, delta);
    }, 0);
    if (score < bestScore) {
      bestScore = score;
      best = candidate;
    }
  }
  return best;
}

export function buildLoftBody(
  firstSketch: Sketch,
  firstEntityId: string,
  secondSketch: Sketch,
  secondEntityId: string,
  previous?: Body,
) {
  if (firstSketch.componentId !== secondSketch.componentId)
    throw new Error("Loft profiles must belong to the same component.");
  if (firstSketch.id === secondSketch.id)
    throw new Error("Loft needs profiles from two distinct sketches.");
  const firstProfile = profileSelection(firstSketch, [firstEntityId])[0];
  const secondProfile = profileSelection(secondSketch, [secondEntityId])[0];
  if (!convexProfile(firstProfile) || !convexProfile(secondProfile))
    throw new Error("Loft currently requires two convex closed profiles.");
  const firstWorld = firstProfile.map((point) => sketchPointToWorld(firstSketch, point));
  const secondWorld = secondProfile.map((point) => sketchPointToWorld(secondSketch, point));
  const firstCenter = boundsCenter(firstWorld).center;
  const secondCenter = boundsCenter(secondWorld).center;
  const direction = normalize(subtract(secondCenter, firstCenter));
  const firstNormal = sketchBasis(firstSketch).normal;
  const secondNormal = sketchBasis(secondSketch).normal;
  if (Math.abs(dot(firstNormal, secondNormal)) < 0.85)
    throw new Error("Loft currently requires approximately parallel profile sketch planes.");
  if (Math.abs(dot(firstNormal, direction)) < 0.7 || Math.abs(dot(secondNormal, direction)) < 0.7)
    throw new Error("Loft profiles must be separated primarily normal to their sketch planes.");
  const count = Math.max(16, Math.min(96, Math.max(firstWorld.length, secondWorld.length)));
  let first = resampleClosedLoop(firstWorld, count);
  let second = resampleClosedLoop(secondWorld, count);
  if (dot(newellNormal(first), direction) < 0) first = [...first].reverse();
  if (dot(newellNormal(second), direction) < 0) second = [...second].reverse();
  second = alignLoftLoops(first, second);
  const bounds = boundsCenter([...first, ...second]);
  return makeBody("Loft", {
    ...previous,
    componentId: previous?.componentId ?? firstSketch.componentId,
    name: previous?.name ?? `${firstSketch.name} to ${secondSketch.name} loft`,
    role: previous?.role ?? "solid",
    sourceSketchId: firstSketch.id,
    position: bounds.center,
    rotation: previous?.rotation ?? [0, 0, 0],
    size: bounds.size,
    profile: undefined,
    profileHoles: undefined,
    orientation: undefined,
    sweep: undefined,
    loft: {
      sections: [
        first.map((point) => subtract(point, bounds.center)),
        second.map((point) => subtract(point, bounds.center)),
      ],
    },
  });
}
