import type { BenchProject, Vec3 } from "./benchcad-model";
import type { TopologyElement } from "./benchcad-topology";

export interface MaterialDefinition {
  id: string;
  name: string;
  density: number;
}

export const MATERIALS: MaterialDefinition[] = [
  { id: "generic", name: "Generic material", density: 1000 },
  { id: "pla", name: "PLA", density: 1240 },
  { id: "petg", name: "PETG", density: 1270 },
  { id: "abs", name: "ABS", density: 1040 },
  { id: "aluminum-6061", name: "Aluminum 6061", density: 2700 },
  { id: "steel", name: "Carbon steel", density: 7850 },
  { id: "stainless-steel", name: "Stainless steel", density: 8000 },
  { id: "brass", name: "Brass", density: 8500 },
  { id: "copper", name: "Copper", density: 8960 },
  { id: "oak", name: "Oak", density: 700 },
  { id: "birch-plywood", name: "Birch plywood", density: 680 },
  { id: "custom", name: "Custom density", density: 1000 },
];

export const DEFAULT_MATERIAL_ID = "generic";

export type InertiaTensor = [Vec3, Vec3, Vec3];

export interface MassProperties {
  volume: number;
  surfaceArea: number;
  centroid: Vec3;
  mass: number;
  inertia: InertiaTensor;
  principalMoments: Vec3;
  bodyCount: number;
}

export interface TopologyMeasurement {
  kind: TopologyElement["kind"] | null;
  count: number;
  totalArea?: number;
  totalLength?: number;
  distance?: number;
  delta?: Vec3;
  normalAngle?: number;
}

const zeroTensor = (): InertiaTensor => [
  [0, 0, 0],
  [0, 0, 0],
  [0, 0, 0],
];

const determinant = (matrix: InertiaTensor) =>
  matrix[0][0] *
    (matrix[1][1] * matrix[2][2] - matrix[1][2] * matrix[2][1]) -
  matrix[0][1] *
    (matrix[1][0] * matrix[2][2] - matrix[1][2] * matrix[2][0]) +
  matrix[0][2] *
    (matrix[1][0] * matrix[2][1] - matrix[1][1] * matrix[2][0]);

export function principalMoments(matrix: InertiaTensor): Vec3 {
  const offDiagonal =
    matrix[0][1] ** 2 + matrix[0][2] ** 2 + matrix[1][2] ** 2;
  if (offDiagonal <= 1e-24)
    return [matrix[0][0], matrix[1][1], matrix[2][2]].sort(
      (first, second) => first - second,
    ) as Vec3;
  const mean = (matrix[0][0] + matrix[1][1] + matrix[2][2]) / 3;
  const spread =
    (matrix[0][0] - mean) ** 2 +
    (matrix[1][1] - mean) ** 2 +
    (matrix[2][2] - mean) ** 2 +
    2 * offDiagonal;
  const scale = Math.sqrt(spread / 6);
  if (scale <= 1e-16) return [mean, mean, mean];
  const normalized = matrix.map((row, rowIndex) =>
    row.map(
      (value, columnIndex) =>
        (value - (rowIndex === columnIndex ? mean : 0)) / scale,
    ),
  ) as InertiaTensor;
  const ratio = Math.max(-1, Math.min(1, determinant(normalized) / 2));
  const angle = Math.acos(ratio) / 3;
  const largest = mean + 2 * scale * Math.cos(angle);
  const smallest = mean + 2 * scale * Math.cos(angle + (2 * Math.PI) / 3);
  const middle = 3 * mean - largest - smallest;
  return [smallest, middle, largest]
    .map((value) => (Math.abs(value) < 1e-12 ? 0 : value))
    .sort((first, second) => first - second) as Vec3;
}

export function materialDensity(materialId?: string, density?: number) {
  if (Number.isFinite(density) && Number(density) > 0) return Number(density);
  return (
    MATERIALS.find((material) => material.id === materialId)?.density ??
    MATERIALS[0].density
  );
}

export function densityPerProjectUnit(
  densityKgPerCubicMeter: number,
  units: BenchProject["units"],
) {
  const metersPerUnit: Record<BenchProject["units"], number> = {
    mm: 0.001,
    cm: 0.01,
    in: 0.0254,
    m: 1,
  };
  return densityKgPerCubicMeter * metersPerUnit[units] ** 3;
}

function vertexAt(vertices: ArrayLike<number>, index: number): Vec3 {
  return [
    Number(vertices[index * 3]),
    Number(vertices[index * 3 + 1]),
    Number(vertices[index * 3 + 2]),
  ];
}

export function computeMeshMassProperties(
  vertices: ArrayLike<number>,
  indices?: ArrayLike<number> | null,
  densityKgPerUnit = 1,
): MassProperties {
  const vertexCount = Math.floor(vertices.length / 3);
  const triangleIndices = indices
    ? Array.from(indices, Number)
    : Array.from({ length: vertexCount }, (_, index) => index);
  let signedVolume = 0;
  let surfaceArea = 0;
  const firstMoment: Vec3 = [0, 0, 0];
  let integralX2 = 0;
  let integralY2 = 0;
  let integralZ2 = 0;
  let integralXY = 0;
  let integralXZ = 0;
  let integralYZ = 0;

  for (let offset = 0; offset + 2 < triangleIndices.length; offset += 3) {
    const a = vertexAt(vertices, triangleIndices[offset]);
    const b = vertexAt(vertices, triangleIndices[offset + 1]);
    const c = vertexAt(vertices, triangleIndices[offset + 2]);
    const ab: Vec3 = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
    const ac: Vec3 = [c[0] - a[0], c[1] - a[1], c[2] - a[2]];
    const surfaceCross: Vec3 = [
      ab[1] * ac[2] - ab[2] * ac[1],
      ab[2] * ac[0] - ab[0] * ac[2],
      ab[0] * ac[1] - ab[1] * ac[0],
    ];
    surfaceArea += Math.hypot(...surfaceCross) / 2;
    const crossBC: Vec3 = [
      b[1] * c[2] - b[2] * c[1],
      b[2] * c[0] - b[0] * c[2],
      b[0] * c[1] - b[1] * c[0],
    ];
    const tetraVolume =
      (a[0] * crossBC[0] + a[1] * crossBC[1] + a[2] * crossBC[2]) /
      6;
    signedVolume += tetraVolume;
    for (let axis = 0; axis < 3; axis += 1)
      firstMoment[axis] +=
        (tetraVolume * (a[axis] + b[axis] + c[axis])) / 4;

    const squareIntegral = (axis: number) =>
      (tetraVolume / 10) *
      (a[axis] ** 2 +
        b[axis] ** 2 +
        c[axis] ** 2 +
        a[axis] * b[axis] +
        a[axis] * c[axis] +
        b[axis] * c[axis]);
    const productIntegral = (first: number, second: number) =>
      (tetraVolume / 20) *
      (2 *
        (a[first] * a[second] +
          b[first] * b[second] +
          c[first] * c[second]) +
        a[first] * b[second] +
        a[second] * b[first] +
        a[first] * c[second] +
        a[second] * c[first] +
        b[first] * c[second] +
        b[second] * c[first]);
    integralX2 += squareIntegral(0);
    integralY2 += squareIntegral(1);
    integralZ2 += squareIntegral(2);
    integralXY += productIntegral(0, 1);
    integralXZ += productIntegral(0, 2);
    integralYZ += productIntegral(1, 2);
  }

  const orientation = signedVolume < 0 ? -1 : 1;
  const volume = Math.abs(signedVolume);
  if (volume <= 1e-14)
    return {
      volume: 0,
      surfaceArea,
      centroid: [0, 0, 0],
      mass: 0,
      inertia: zeroTensor(),
      principalMoments: [0, 0, 0],
      bodyCount: 0,
    };
  const centroid = firstMoment.map(
    (value) => (value * orientation) / volume,
  ) as Vec3;
  const mass = volume * densityKgPerUnit;
  integralX2 *= orientation;
  integralY2 *= orientation;
  integralZ2 *= orientation;
  integralXY *= orientation;
  integralXZ *= orientation;
  integralYZ *= orientation;
  const origin: InertiaTensor = [
    [
      densityKgPerUnit * (integralY2 + integralZ2),
      -densityKgPerUnit * integralXY,
      -densityKgPerUnit * integralXZ,
    ],
    [
      -densityKgPerUnit * integralXY,
      densityKgPerUnit * (integralX2 + integralZ2),
      -densityKgPerUnit * integralYZ,
    ],
    [
      -densityKgPerUnit * integralXZ,
      -densityKgPerUnit * integralYZ,
      densityKgPerUnit * (integralX2 + integralY2),
    ],
  ];
  const inertia = origin.map((row, rowIndex) =>
    row.map((value, columnIndex) => {
      if (rowIndex === columnIndex)
        return (
          value -
          mass *
            centroid.reduce(
              (sum, coordinate, axis) =>
                sum + (axis === rowIndex ? 0 : coordinate ** 2),
              0,
            )
        );
      return value + mass * centroid[rowIndex] * centroid[columnIndex];
    }),
  ) as InertiaTensor;
  return {
    volume,
    surfaceArea,
    centroid,
    mass,
    inertia,
    principalMoments: principalMoments(inertia),
    bodyCount: 1,
  };
}

export function combineMassProperties(parts: MassProperties[]): MassProperties {
  const mass = parts.reduce((sum, part) => sum + part.mass, 0);
  const centroid = parts
    .reduce(
      (sum, part) =>
        sum.map(
          (value, axis) => value + part.centroid[axis] * part.mass,
        ) as Vec3,
      [0, 0, 0] as Vec3,
    )
    .map((value) => (mass > 0 ? value / mass : 0)) as Vec3;
  const inertia = zeroTensor();
  parts.forEach((part) => {
    const delta = part.centroid.map(
      (value, axis) => value - centroid[axis],
    ) as Vec3;
    for (let row = 0; row < 3; row += 1) {
      for (let column = 0; column < 3; column += 1) {
        const shift =
          row === column
            ? part.mass *
              delta.reduce(
                (sum, value, axis) =>
                  sum + (axis === row ? 0 : value ** 2),
                0,
              )
            : -part.mass * delta[row] * delta[column];
        inertia[row][column] += part.inertia[row][column] + shift;
      }
    }
  });
  return {
    volume: parts.reduce((sum, part) => sum + part.volume, 0),
    surfaceArea: parts.reduce((sum, part) => sum + part.surfaceArea, 0),
    centroid,
    mass,
    inertia,
    principalMoments: principalMoments(inertia),
    bodyCount: parts.reduce((sum, part) => sum + part.bodyCount, 0),
  };
}

export function summarizeTopologySelection(
  selections: TopologyElement[],
): TopologyMeasurement {
  const kind = selections[0]?.kind ?? null;
  const matching = selections.filter((selection) => selection.kind === kind);
  const summary: TopologyMeasurement = { kind, count: matching.length };
  if (kind === "face") {
    const faces = matching.filter((selection) => selection.kind === "face");
    summary.totalArea = faces.reduce((sum, face) => sum + face.area, 0);
    if (faces.length === 2 && faces[0].normal && faces[1].normal) {
      const cosine = Math.max(
        -1,
        Math.min(
          1,
          faces[0].normal.reduce(
            (sum, value, axis) => sum + value * faces[1].normal![axis],
            0,
          ),
        ),
      );
      summary.normalAngle = (Math.acos(Math.abs(cosine)) * 180) / Math.PI;
    }
  }
  if (kind === "edge")
    summary.totalLength = matching
      .filter((selection) => selection.kind === "edge")
      .reduce((sum, edge) => sum + edge.length, 0);
  if (kind === "vertex" && matching.length === 2) {
    const first = matching[0].centroid;
    const second = matching[1].centroid;
    summary.delta = second.map((value, axis) => value - first[axis]) as Vec3;
    summary.distance = Math.hypot(...summary.delta);
  }
  return summary;
}
