import { bodyPointToLocal } from "./benchcad-model";
import type { Body, EdgeFinishReference, Vec3 } from "./benchcad-model";
import type { TopologyEdge } from "./benchcad-topology";

export function topologyPointToBodyLocal(
  body: Body,
  pointInWorldCoordinates: Vec3,
): Vec3 {
  return bodyPointToLocal(body, pointInWorldCoordinates);
}

export function normalizedEdgeReference(
  body: Body,
  edge: TopologyEdge,
): EdgeFinishReference {
  if (edge.closed || edge.points.length !== 1)
    throw new Error("Choose individual straight edges, not a closed edge loop.");
  const endpoints = edge.points[0].map((point) => {
    const local = topologyPointToBodyLocal(body, point);
    return local.map(
      (value, axis) => value / Math.max(0.000001, body.size[axis]),
    ) as Vec3;
  }) as [Vec3, Vec3];
  return { topologyId: edge.id, endpoints };
}
