export type TopologySelectionMode = "body" | "face" | "edge" | "vertex";
export type TopologyKind = Exclude<TopologySelectionMode, "body">;
export type TopologyVec3 = [number, number, number];

interface TopologyElementBase {
  id: string;
  bodyId: string;
  ownerId: string;
  index: number;
  centroid: TopologyVec3;
}

export interface TopologyFace extends TopologyElementBase {
  kind: "face";
  triangleIndices: number[];
  points: TopologyVec3[];
  area: number;
  normal: TopologyVec3 | null;
  planar: boolean;
}

export interface TopologyEdge extends TopologyElementBase {
  kind: "edge";
  segments: Array<[number, number]>;
  points: Array<[TopologyVec3, TopologyVec3]>;
  faceIds: string[];
  length: number;
  closed: boolean;
}

export interface TopologyVertex extends TopologyElementBase {
  kind: "vertex";
  vertexIndex: number;
  position: TopologyVec3;
  edgeIds: string[];
  singular: boolean;
}

export type TopologyElement = TopologyFace | TopologyEdge | TopologyVertex;

export interface MeshTopology {
  bodyId: string;
  ownerId: string;
  vertices: TopologyVec3[];
  faces: TopologyFace[];
  edges: TopologyEdge[];
  verticesOfInterest: TopologyVertex[];
  faceIndexByTriangle: number[];
}

interface TriangleData {
  vertices: [number, number, number];
  normal: TopologyVec3;
  area: number;
  centroid: TopologyVec3;
}

const add = (a: TopologyVec3, b: TopologyVec3): TopologyVec3 => [
  a[0] + b[0],
  a[1] + b[1],
  a[2] + b[2],
];

const subtract = (a: TopologyVec3, b: TopologyVec3): TopologyVec3 => [
  a[0] - b[0],
  a[1] - b[1],
  a[2] - b[2],
];

const scale = (value: TopologyVec3, factor: number): TopologyVec3 => [
  value[0] * factor,
  value[1] * factor,
  value[2] * factor,
];

const dot = (a: TopologyVec3, b: TopologyVec3) =>
  a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

const cross = (a: TopologyVec3, b: TopologyVec3): TopologyVec3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];

const length = (value: TopologyVec3) => Math.sqrt(dot(value, value));

const normalize = (value: TopologyVec3): TopologyVec3 => {
  const magnitude = length(value);
  return magnitude > 1e-12 ? scale(value, 1 / magnitude) : [0, 0, 0];
};

const average = (values: TopologyVec3[]): TopologyVec3 =>
  values.length
    ? scale(values.reduce(add, [0, 0, 0] as TopologyVec3), 1 / values.length)
    : [0, 0, 0];

const edgeKey = (first: number, second: number) =>
  first < second ? `${first}:${second}` : `${second}:${first}`;

const compareNumbers = (first: number[], second: number[]) => {
  for (let index = 0; index < Math.max(first.length, second.length); index += 1) {
    const delta = (first[index] ?? 0) - (second[index] ?? 0);
    if (Math.abs(delta) > 1e-8) return delta;
  }
  return 0;
};

const sortSignature = (centroid: TopologyVec3, measure: number, fallback: number) => [
  fallback,
  Number(centroid[0].toFixed(6)),
  Number(centroid[1].toFixed(6)),
  Number(centroid[2].toFixed(6)),
  Number(measure.toFixed(6)),
];

export function topologyElementById(
  topology: MeshTopology,
  id: string,
): TopologyElement | undefined {
  return [
    ...topology.faces,
    ...topology.edges,
    ...topology.verticesOfInterest,
  ].find((element) => element.id === id);
}

export function analyzeMeshTopology(
  bodyId: string,
  positions: ArrayLike<number>,
  meshIndices?: ArrayLike<number> | null,
  ownerId = bodyId,
): MeshTopology {
  const rawVertexCount = Math.floor(positions.length / 3);
  const rawVertices = Array.from({ length: rawVertexCount }, (_, index) => [
    Number(positions[index * 3]),
    Number(positions[index * 3 + 1]),
    Number(positions[index * 3 + 2]),
  ] as TopologyVec3);
  const boundsMin: TopologyVec3 = [Infinity, Infinity, Infinity];
  const boundsMax: TopologyVec3 = [-Infinity, -Infinity, -Infinity];
  rawVertices.forEach((vertex) => {
    for (let axis = 0; axis < 3; axis += 1) {
      boundsMin[axis] = Math.min(boundsMin[axis], vertex[axis]);
      boundsMax[axis] = Math.max(boundsMax[axis], vertex[axis]);
    }
  });
  const diagonal = length(subtract(boundsMax, boundsMin));
  const tolerance = Math.max(1e-7, diagonal * 1e-6);
  const vertices: TopologyVec3[] = [];
  const canonicalByKey = new Map<string, number>();
  const rawToCanonical = rawVertices.map((vertex) => {
    const key = vertex
      .map((value) => Math.round(value / tolerance))
      .join(":");
    const existing = canonicalByKey.get(key);
    if (existing !== undefined) return existing;
    const index = vertices.length;
    canonicalByKey.set(key, index);
    vertices.push(vertex);
    return index;
  });
  const indices = meshIndices
    ? Array.from(meshIndices, Number)
    : Array.from({ length: rawVertexCount }, (_, index) => index);
  const triangleCount = Math.floor(indices.length / 3);
  const triangles: TriangleData[] = [];
  for (let triangleIndex = 0; triangleIndex < triangleCount; triangleIndex += 1) {
    const raw = [
      indices[triangleIndex * 3],
      indices[triangleIndex * 3 + 1],
      indices[triangleIndex * 3 + 2],
    ];
    const canonical = raw.map((index) => rawToCanonical[index]) as [number, number, number];
    const a = vertices[canonical[0]];
    const b = vertices[canonical[1]];
    const c = vertices[canonical[2]];
    const normalVector = cross(subtract(b, a), subtract(c, a));
    triangles.push({
      vertices: canonical,
      normal: normalize(normalVector),
      area: length(normalVector) / 2,
      centroid: scale(add(add(a, b), c), 1 / 3),
    });
  }

  const parent = Array.from({ length: triangleCount }, (_, index) => index);
  const find = (value: number): number => {
    let root = value;
    while (parent[root] !== root) root = parent[root];
    while (parent[value] !== value) {
      const next = parent[value];
      parent[value] = root;
      value = next;
    }
    return root;
  };
  const unite = (first: number, second: number) => {
    const firstRoot = find(first);
    const secondRoot = find(second);
    if (firstRoot !== secondRoot) parent[secondRoot] = firstRoot;
  };
  const trianglesByEdge = new Map<string, number[]>();
  triangles.forEach((triangle, triangleIndex) => {
    const [a, b, c] = triangle.vertices;
    [[a, b], [b, c], [c, a]].forEach(([first, second]) => {
      const key = edgeKey(first, second);
      trianglesByEdge.set(key, [
        ...(trianglesByEdge.get(key) ?? []),
        triangleIndex,
      ]);
    });
  });
  const smoothThreshold = Math.cos((35 * Math.PI) / 180);
  trianglesByEdge.forEach((adjacent) => {
    if (adjacent.length !== 2) return;
    const [first, second] = adjacent;
    if (dot(triangles[first].normal, triangles[second].normal) >= smoothThreshold)
      unite(first, second);
  });

  const triangleGroups = new Map<number, number[]>();
  triangles.forEach((_, triangleIndex) => {
    const root = find(triangleIndex);
    triangleGroups.set(root, [
      ...(triangleGroups.get(root) ?? []),
      triangleIndex,
    ]);
  });
  const faceDrafts = [...triangleGroups.values()].map((triangleIndices) => {
    const area = triangleIndices.reduce(
      (total, triangleIndex) => total + triangles[triangleIndex].area,
      0,
    );
    const centroid = area > 1e-12
      ? scale(
          triangleIndices.reduce(
            (sum, triangleIndex) =>
              add(
                sum,
                scale(
                  triangles[triangleIndex].centroid,
                  triangles[triangleIndex].area,
                ),
              ),
            [0, 0, 0] as TopologyVec3,
          ),
          1 / area,
        )
      : average(triangleIndices.map((index) => triangles[index].centroid));
    const referenceNormal = triangles[triangleIndices[0]]?.normal ?? [0, 0, 0];
    const planar = triangleIndices.every(
      (triangleIndex) =>
        dot(referenceNormal, triangles[triangleIndex].normal) >=
        Math.cos(Math.PI / 180),
    );
    const pointIndices = [
      ...new Set(
        triangleIndices.flatMap((triangleIndex) =>
          triangles[triangleIndex].vertices,
        ),
      ),
    ];
    return {
      triangleIndices,
      points: pointIndices.map((vertexIndex) => vertices[vertexIndex]),
      area,
      centroid,
      planar,
      normal: planar ? referenceNormal : null,
    };
  });
  faceDrafts.sort((first, second) =>
    compareNumbers(
      sortSignature(first.centroid, first.area, first.triangleIndices[0]),
      sortSignature(second.centroid, second.area, second.triangleIndices[0]),
    ),
  );
  const faces: TopologyFace[] = faceDrafts.map((face, index) => ({
    id: `${ownerId}:face:${index}`,
    bodyId,
    ownerId,
    index,
    kind: "face",
    ...face,
  }));
  const faceIndexByTriangle = Array.from({ length: triangleCount }, () => -1);
  faces.forEach((face) =>
    face.triangleIndices.forEach((triangleIndex) => {
      faceIndexByTriangle[triangleIndex] = face.index;
    }),
  );

  interface BoundarySegment {
    vertices: [number, number];
    faceIndices: number[];
  }
  const boundaryByPair = new Map<string, BoundarySegment[]>();
  trianglesByEdge.forEach((adjacent, key) => {
    const faceIndices = [
      ...new Set(adjacent.map((triangleIndex) => faceIndexByTriangle[triangleIndex])),
    ].filter((index) => index >= 0).sort((a, b) => a - b);
    if (faceIndices.length === 1 && adjacent.length > 1) return;
    const pair = faceIndices.length > 1
      ? faceIndices.slice(0, 2)
      : [faceIndices[0] ?? -1, -1];
    const [first, second] = key.split(":").map(Number) as [number, number];
    const pairKey = `${pair[0]}:${pair[1]}`;
    boundaryByPair.set(pairKey, [
      ...(boundaryByPair.get(pairKey) ?? []),
      { vertices: [first, second], faceIndices: pair },
    ]);
  });

  const edgeDrafts: Array<{
    segments: Array<[number, number]>;
    faceIndices: number[];
    centroid: TopologyVec3;
    length: number;
    closed: boolean;
  }> = [];
  boundaryByPair.forEach((segments) => {
    const segmentIndicesByVertex = new Map<number, number[]>();
    segments.forEach((segment, segmentIndex) =>
      segment.vertices.forEach((vertexIndex) =>
        segmentIndicesByVertex.set(vertexIndex, [
          ...(segmentIndicesByVertex.get(vertexIndex) ?? []),
          segmentIndex,
        ]),
      ),
    );
    const remaining = new Set(segments.map((_, index) => index));
    while (remaining.size) {
      const seed = remaining.values().next().value as number;
      const queue = [seed];
      const component: BoundarySegment[] = [];
      remaining.delete(seed);
      while (queue.length) {
        const current = queue.pop()!;
        const segment = segments[current];
        component.push(segment);
        segment.vertices.forEach((vertexIndex) =>
          (segmentIndicesByVertex.get(vertexIndex) ?? []).forEach((candidate) => {
            if (!remaining.has(candidate)) return;
            remaining.delete(candidate);
            queue.push(candidate);
          }),
        );
      }
      const componentSegments = component.map((segment) => segment.vertices);
      const degrees = new Map<number, number>();
      let totalLength = 0;
      let weightedCentroid: TopologyVec3 = [0, 0, 0];
      componentSegments.forEach(([first, second]) => {
        degrees.set(first, (degrees.get(first) ?? 0) + 1);
        degrees.set(second, (degrees.get(second) ?? 0) + 1);
        const segmentLength = length(subtract(vertices[second], vertices[first]));
        totalLength += segmentLength;
        weightedCentroid = add(
          weightedCentroid,
          scale(average([vertices[first], vertices[second]]), segmentLength),
        );
      });
      edgeDrafts.push({
        segments: componentSegments,
        faceIndices: component[0].faceIndices,
        centroid:
          totalLength > 1e-12
            ? scale(weightedCentroid, 1 / totalLength)
            : [0, 0, 0],
        length: totalLength,
        closed: [...degrees.values()].every((degree) => degree === 2),
      });
    }
  });
  edgeDrafts.sort((first, second) => {
    const pairDelta = compareNumbers(first.faceIndices, second.faceIndices);
    return pairDelta || compareNumbers(
      sortSignature(first.centroid, first.length, first.segments[0]?.[0] ?? 0),
      sortSignature(second.centroid, second.length, second.segments[0]?.[0] ?? 0),
    );
  });
  const edges: TopologyEdge[] = edgeDrafts.map((edge, index) => ({
    id: `${ownerId}:edge:${index}`,
    bodyId,
    ownerId,
    index,
    kind: "edge",
    centroid: edge.centroid,
    segments: edge.segments,
    points: edge.segments.map(([first, second]) => [vertices[first], vertices[second]]),
    faceIds: edge.faceIndices
      .filter((faceIndex) => faceIndex >= 0)
      .map((faceIndex) => faces[faceIndex].id),
    length: edge.length,
    closed: edge.closed,
  }));

  const edgeIndicesByVertex = new Map<number, Set<number>>();
  edges.forEach((edge) =>
    edge.segments.forEach((segment) =>
      segment.forEach((vertexIndex) => {
        const existing = edgeIndicesByVertex.get(vertexIndex) ?? new Set<number>();
        existing.add(edge.index);
        edgeIndicesByVertex.set(vertexIndex, existing);
      }),
    ),
  );
  const triangleIndicesByVertex = new Map<number, number[]>();
  triangles.forEach((triangle, triangleIndex) =>
    triangle.vertices.forEach((vertexIndex) =>
      triangleIndicesByVertex.set(vertexIndex, [
        ...(triangleIndicesByVertex.get(vertexIndex) ?? []),
        triangleIndex,
      ]),
    ),
  );
  const vertexDrafts = vertices.flatMap((position, vertexIndex) => {
    const edgeIndices = [...(edgeIndicesByVertex.get(vertexIndex) ?? [])];
    const incidentTriangles = triangleIndicesByVertex.get(vertexIndex) ?? [];
    const incidentFaces = new Set(
      incidentTriangles.map((triangleIndex) => faceIndexByTriangle[triangleIndex]),
    );
    let singular = false;
    if (incidentFaces.size === 1 && incidentTriangles.length >= 4) {
      for (let first = 0; first < incidentTriangles.length && !singular; first += 1)
        for (let second = first + 1; second < incidentTriangles.length; second += 1)
          if (
            dot(
              triangles[incidentTriangles[first]].normal,
              triangles[incidentTriangles[second]].normal,
            ) < Math.cos(Math.PI / 4)
          ) {
            singular = true;
            break;
          }
    }
    if (edgeIndices.length < 3 && !singular) return [];
    return [{ vertexIndex, position, edgeIndices, singular }];
  });
  vertexDrafts.sort((first, second) => first.vertexIndex - second.vertexIndex);
  const verticesOfInterest: TopologyVertex[] = vertexDrafts.map((vertex, index) => ({
    id: `${ownerId}:vertex:${index}`,
    bodyId,
    ownerId,
    index,
    kind: "vertex",
    centroid: vertex.position,
    position: vertex.position,
    vertexIndex: vertex.vertexIndex,
    edgeIds: vertex.edgeIndices.map((edgeIndex) => edges[edgeIndex].id),
    singular: vertex.singular,
  }));

  return {
    bodyId,
    ownerId,
    vertices,
    faces,
    edges,
    verticesOfInterest,
    faceIndexByTriangle,
  };
}
