import {
  drawingSheetDimensions,
  uid,
  type BenchProject,
  type Body,
  type DrawingDimension,
  type DrawingNote,
  type DrawingSheet,
  type DrawingView,
  type DrawingViewOrientation,
  type Vec3,
} from "./benchcad-model";

export interface DrawingMesh {
  targetId: string;
  vertices: ArrayLike<number>;
  indices: ArrayLike<number>;
}

export type DrawingLineStyle =
  | "visible"
  | "hidden"
  | "section"
  | "hatch"
  | "dimension"
  | "border"
  | "title";

export interface DrawingLinePrimitive {
  kind: "line";
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  style: DrawingLineStyle;
  viewId?: string;
}

export interface DrawingTextPrimitive {
  kind: "text";
  x: number;
  y: number;
  text: string;
  size: number;
  align?: "start" | "middle" | "end";
  weight?: "normal" | "bold";
  viewId?: string;
}

export type DrawingPrimitive = DrawingLinePrimitive | DrawingTextPrimitive;

export interface DrawingBounds {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
}

export interface ProjectedDrawingView {
  viewId: string;
  lines: Array<{
    a: [number, number];
    b: [number, number];
    hidden: boolean;
  }>;
  sectionLines: Array<{
    a: [number, number];
    b: [number, number];
  }>;
  bounds: DrawingBounds;
}

export interface RenderedDrawingSheet {
  width: number;
  height: number;
  primitives: DrawingPrimitive[];
  viewBounds: Record<string, DrawingBounds>;
}

const EPSILON = 1e-7;

const add = (a: Vec3, b: Vec3): Vec3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const subtract = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const scale = (a: Vec3, amount: number): Vec3 => [a[0] * amount, a[1] * amount, a[2] * amount];
const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec3, b: Vec3): Vec3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
const length = (a: Vec3) => Math.hypot(a[0], a[1], a[2]);
const normalize = (a: Vec3): Vec3 => {
  const magnitude = length(a) || 1;
  return scale(a, 1 / magnitude);
};

const pointAt = (vertices: ArrayLike<number>, index: number): Vec3 => [
  Number(vertices[index * 3]),
  Number(vertices[index * 3 + 1]),
  Number(vertices[index * 3 + 2]),
];

const pointKey = (point: Vec3) => point.map((value) => value.toFixed(6)).join(",");

function viewBasis(orientation: DrawingViewOrientation) {
  const bases: Record<
    DrawingViewOrientation,
    { u: Vec3; v: Vec3; depth: Vec3 }
  > = {
    front: { u: [1, 0, 0], v: [0, 0, 1], depth: [0, -1, 0] },
    back: { u: [-1, 0, 0], v: [0, 0, 1], depth: [0, 1, 0] },
    top: { u: [1, 0, 0], v: [0, 1, 0], depth: [0, 0, 1] },
    bottom: { u: [1, 0, 0], v: [0, -1, 0], depth: [0, 0, -1] },
    left: { u: [0, 1, 0], v: [0, 0, 1], depth: [-1, 0, 0] },
    right: { u: [0, -1, 0], v: [0, 0, 1], depth: [1, 0, 0] },
    iso: {
      u: normalize([1, -1, 0]),
      v: normalize([-1, -1, 2]),
      depth: normalize([1, 1, 1]),
    },
  };
  return bases[orientation];
}

function projectPoint(point: Vec3, orientation: DrawingViewOrientation): [number, number] {
  const basis = viewBasis(orientation);
  return [dot(point, basis.u), dot(point, basis.v)];
}

function emptyBounds(): DrawingBounds {
  return { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity };
}

function includePoint(bounds: DrawingBounds, point: [number, number]) {
  bounds.minX = Math.min(bounds.minX, point[0]);
  bounds.minY = Math.min(bounds.minY, point[1]);
  bounds.maxX = Math.max(bounds.maxX, point[0]);
  bounds.maxY = Math.max(bounds.maxY, point[1]);
}

function normalizedBounds(bounds: DrawingBounds): DrawingBounds {
  if (Number.isFinite(bounds.minX)) return bounds;
  return { minX: -10, minY: -10, maxX: 10, maxY: 10 };
}

function rotatePoint(point: Vec3, rotation: Vec3): Vec3 {
  const [rx, ry, rz] = rotation.map((value) => (value * Math.PI) / 180) as Vec3;
  let [x, y, z] = point;
  [y, z] = [y * Math.cos(rx) - z * Math.sin(rx), y * Math.sin(rx) + z * Math.cos(rx)];
  [x, z] = [x * Math.cos(ry) + z * Math.sin(ry), -x * Math.sin(ry) + z * Math.cos(ry)];
  [x, y] = [x * Math.cos(rz) - y * Math.sin(rz), x * Math.sin(rz) + y * Math.cos(rz)];
  return [x, y, z];
}

export function bodyFallbackDrawingMesh(body: Body): DrawingMesh {
  const half = body.size.map((value) => value / 2) as Vec3;
  const mirror = body.mirrorAxes ?? [1, 1, 1];
  const corners: Vec3[] = [
    [-half[0], -half[1], -half[2]], [half[0], -half[1], -half[2]],
    [half[0], half[1], -half[2]], [-half[0], half[1], -half[2]],
    [-half[0], -half[1], half[2]], [half[0], -half[1], half[2]],
    [half[0], half[1], half[2]], [-half[0], half[1], half[2]],
  ].map((point) =>
    add(
      rotatePoint(
        [point[0] * mirror[0], point[1] * mirror[1], point[2] * mirror[2]],
        body.rotation,
      ),
      body.position,
    ),
  );
  return {
    targetId: body.id,
    vertices: corners.flat(),
    indices: [
      0, 2, 1, 0, 3, 2, 4, 5, 6, 4, 6, 7,
      0, 1, 5, 0, 5, 4, 1, 2, 6, 1, 6, 5,
      2, 3, 7, 2, 7, 6, 3, 0, 4, 3, 4, 7,
    ],
  };
}

export function drawingMeshesForBodies(
  bodies: Body[],
  meshes: DrawingMesh[],
  sourceBodyIds: string[],
) {
  const source = new Set(sourceBodyIds.length ? sourceBodyIds : bodies.map((body) => body.id));
  const exact = new Map(meshes.map((mesh) => [mesh.targetId, mesh]));
  return bodies
    .filter((body) => body.visible && source.has(body.id))
    .map((body) => exact.get(body.id) ?? bodyFallbackDrawingMesh(body));
}

interface EdgeRecord {
  a: Vec3;
  b: Vec3;
  normals: Vec3[];
  facing: boolean[];
}

function meshProjection(mesh: DrawingMesh, orientation: DrawingViewOrientation) {
  const basis = viewBasis(orientation);
  const edges = new Map<string, EdgeRecord>();
  for (let index = 0; index + 2 < mesh.indices.length; index += 3) {
    const points = [0, 1, 2].map((slot) => pointAt(mesh.vertices, Number(mesh.indices[index + slot])));
    const normal = normalize(cross(subtract(points[1], points[0]), subtract(points[2], points[0])));
    const facing = dot(normal, basis.depth) >= -EPSILON;
    for (const [first, second] of [[0, 1], [1, 2], [2, 0]] as const) {
      const a = points[first];
      const b = points[second];
      const keys = [pointKey(a), pointKey(b)].sort();
      const key = `${keys[0]}|${keys[1]}`;
      const record = edges.get(key) ?? { a, b, normals: [], facing: [] };
      record.normals.push(normal);
      record.facing.push(facing);
      edges.set(key, record);
    }
  }
  return [...edges.values()]
    .filter((edge) => {
      if (edge.normals.length < 2) return true;
      const normalDot = Math.abs(dot(edge.normals[0], edge.normals[1]));
      const silhouette = edge.facing.some(Boolean) && edge.facing.some((value) => !value);
      return silhouette || normalDot < 0.9945;
    })
    .map((edge) => ({
      a: projectPoint(edge.a, orientation),
      b: projectPoint(edge.b, orientation),
      hidden: !edge.facing.some(Boolean),
    }))
    .filter((edge) => Math.hypot(edge.b[0] - edge.a[0], edge.b[1] - edge.a[1]) > EPSILON);
}

function triangleSection(
  points: [Vec3, Vec3, Vec3],
  axis: number,
  offset: number,
): [Vec3, Vec3] | null {
  const intersections: Vec3[] = [];
  const addUnique = (point: Vec3) => {
    if (!intersections.some((candidate) => length(subtract(candidate, point)) < 1e-6))
      intersections.push(point);
  };
  for (const [first, second] of [[0, 1], [1, 2], [2, 0]] as const) {
    const a = points[first];
    const b = points[second];
    const da = a[axis] - offset;
    const db = b[axis] - offset;
    if (Math.abs(da) < EPSILON) addUnique(a);
    if (Math.abs(db) < EPSILON) addUnique(b);
    if (da * db < -EPSILON) {
      const amount = da / (da - db);
      addUnique(add(a, scale(subtract(b, a), amount)));
    }
  }
  return intersections.length >= 2 ? [intersections[0], intersections[1]] : null;
}

function meshSection(
  mesh: DrawingMesh,
  orientation: DrawingViewOrientation,
  axis: "X" | "Y" | "Z",
  offset: number,
) {
  const axisIndex = { X: 0, Y: 1, Z: 2 }[axis];
  const result: Array<{ a: [number, number]; b: [number, number] }> = [];
  const dedupe = new Set<string>();
  for (let index = 0; index + 2 < mesh.indices.length; index += 3) {
    const points = [0, 1, 2].map((slot) => pointAt(mesh.vertices, Number(mesh.indices[index + slot]))) as [Vec3, Vec3, Vec3];
    const segment = triangleSection(points, axisIndex, offset);
    if (!segment) continue;
    const a = projectPoint(segment[0], orientation);
    const b = projectPoint(segment[1], orientation);
    const key = [a, b]
      .map((point) => point.map((value) => value.toFixed(5)).join(","))
      .sort()
      .join("|");
    if (!dedupe.has(key)) {
      result.push({ a, b });
      dedupe.add(key);
    }
  }
  return result;
}

export function projectDrawingView(
  view: DrawingView,
  bodies: Body[],
  meshes: DrawingMesh[],
): ProjectedDrawingView {
  const sources = drawingMeshesForBodies(bodies, meshes, view.sourceBodyIds);
  const lines = sources.flatMap((mesh) => meshProjection(mesh, view.orientation));
  const sectionLines = view.type === "section"
    ? sources.flatMap((mesh) =>
        meshSection(
          mesh,
          view.orientation,
          view.sectionAxis ?? "Y",
          view.sectionOffset ?? 0,
        ),
      )
    : [];
  const bounds = emptyBounds();
  lines.forEach((line) => {
    includePoint(bounds, line.a);
    includePoint(bounds, line.b);
  });
  sectionLines.forEach((line) => {
    includePoint(bounds, line.a);
    includePoint(bounds, line.b);
  });
  return { viewId: view.id, lines, sectionLines, bounds: normalizedBounds(bounds) };
}

const unitToMillimeters = (units: BenchProject["units"]) =>
  ({ mm: 1, cm: 10, in: 25.4, m: 1000 })[units];

export function recommendedDrawingScale(
  projection: ProjectedDrawingView,
  units: BenchProject["units"],
  availableWidth = 105,
  availableHeight = 70,
) {
  const width = Math.max(EPSILON, projection.bounds.maxX - projection.bounds.minX);
  const height = Math.max(EPSILON, projection.bounds.maxY - projection.bounds.minY);
  const maximum = Math.min(
    availableWidth / (width * unitToMillimeters(units)),
    availableHeight / (height * unitToMillimeters(units)),
  );
  return [10, 5, 2, 1, 0.5, 0.25, 0.2, 0.1, 0.05, 0.02, 0.01].find(
    (candidate) => candidate <= maximum,
  ) ?? 0.01;
}

export function makeDrawingView(
  bodyIds: string[],
  sheet: DrawingSheet,
  overrides: Partial<DrawingView> = {},
): DrawingView {
  const now = new Date().toISOString();
  return {
    id: uid("drawing-view"),
    name: "Front view",
    type: "orthographic",
    orientation: "front",
    sourceBodyIds: [...bodyIds],
    x: sheet.width * 0.38,
    y: sheet.height * 0.42,
    scale: 1,
    showHiddenLines: false,
    sectionAxis: "Y",
    sectionOffset: 0,
    createdAt: now,
    updatedAt: now,
    ...overrides,
  };
}

export function makeDrawingDimension(
  viewId: string,
  kind: DrawingDimension["kind"],
  overrides: Partial<DrawingDimension> = {},
): DrawingDimension {
  const now = new Date().toISOString();
  return {
    id: uid("drawing-dimension"),
    viewId,
    kind,
    offset: 12,
    precision: 2,
    prefix: "",
    suffix: "",
    toleranceUpper: null,
    toleranceLower: null,
    createdAt: now,
    updatedAt: now,
    ...overrides,
  };
}

export function makeDrawingNote(
  text: string,
  sheet: DrawingSheet,
  overrides: Partial<DrawingNote> = {},
): DrawingNote {
  const now = new Date().toISOString();
  return {
    id: uid("drawing-note"),
    text,
    x: sheet.width * 0.08,
    y: sheet.height * 0.12,
    fontSize: 3.5,
    createdAt: now,
    updatedAt: now,
    ...overrides,
  };
}

function mappedPoint(
  point: [number, number],
  projection: ProjectedDrawingView,
  view: DrawingView,
  units: BenchProject["units"],
): [number, number] {
  const centerX = (projection.bounds.minX + projection.bounds.maxX) / 2;
  const centerY = (projection.bounds.minY + projection.bounds.maxY) / 2;
  const factor = unitToMillimeters(units) * view.scale;
  return [view.x + (point[0] - centerX) * factor, view.y - (point[1] - centerY) * factor];
}

function line(
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  style: DrawingLineStyle,
  viewId?: string,
): DrawingLinePrimitive {
  return { kind: "line", x1, y1, x2, y2, style, viewId };
}

function text(
  x: number,
  y: number,
  value: string,
  size: number,
  options: Partial<Omit<DrawingTextPrimitive, "kind" | "x" | "y" | "text" | "size">> = {},
): DrawingTextPrimitive {
  return { kind: "text", x, y, text: value, size, ...options };
}

function toleranceLabel(dimension: DrawingDimension) {
  const upper = dimension.toleranceUpper;
  const lower = dimension.toleranceLower;
  if (upper === null && lower === null) return "";
  if (upper !== null && lower !== null && Math.abs(upper + lower) < EPSILON)
    return ` ±${Math.abs(upper).toFixed(dimension.precision)}`;
  const plus = upper === null ? "" : ` +${upper.toFixed(dimension.precision)}`;
  const minus = lower === null ? "" : ` ${lower.toFixed(dimension.precision)}`;
  return plus + minus;
}

function dimensionPrimitives(
  dimension: DrawingDimension,
  view: DrawingView,
  projection: ProjectedDrawingView,
  sheetBounds: DrawingBounds,
  units: BenchProject["units"],
) {
  const result: DrawingPrimitive[] = [];
  const modelWidth = projection.bounds.maxX - projection.bounds.minX;
  const modelHeight = projection.bounds.maxY - projection.bounds.minY;
  const horizontal = dimension.kind !== "vertical";
  const value = horizontal ? modelWidth : modelHeight;
  const formatted = `${dimension.prefix}${value.toFixed(dimension.precision)}${toleranceLabel(dimension)}${dimension.suffix}`;
  if (horizontal) {
    const y = sheetBounds.maxY + dimension.offset;
    result.push(
      line(sheetBounds.minX, sheetBounds.maxY + 1, sheetBounds.minX, y + 2, "dimension", view.id),
      line(sheetBounds.maxX, sheetBounds.maxY + 1, sheetBounds.maxX, y + 2, "dimension", view.id),
      line(sheetBounds.minX, y, sheetBounds.maxX, y, "dimension", view.id),
      line(sheetBounds.minX, y, sheetBounds.minX + 3, y - 1.3, "dimension", view.id),
      line(sheetBounds.minX, y, sheetBounds.minX + 3, y + 1.3, "dimension", view.id),
      line(sheetBounds.maxX, y, sheetBounds.maxX - 3, y - 1.3, "dimension", view.id),
      line(sheetBounds.maxX, y, sheetBounds.maxX - 3, y + 1.3, "dimension", view.id),
      text((sheetBounds.minX + sheetBounds.maxX) / 2, y - 1.8, `${formatted} ${units}`, 3.1, { align: "middle", viewId: view.id }),
    );
  } else {
    const x = sheetBounds.maxX + dimension.offset;
    result.push(
      line(sheetBounds.maxX + 1, sheetBounds.minY, x + 2, sheetBounds.minY, "dimension", view.id),
      line(sheetBounds.maxX + 1, sheetBounds.maxY, x + 2, sheetBounds.maxY, "dimension", view.id),
      line(x, sheetBounds.minY, x, sheetBounds.maxY, "dimension", view.id),
      line(x, sheetBounds.minY, x - 1.3, sheetBounds.minY + 3, "dimension", view.id),
      line(x, sheetBounds.minY, x + 1.3, sheetBounds.minY + 3, "dimension", view.id),
      line(x, sheetBounds.maxY, x - 1.3, sheetBounds.maxY - 3, "dimension", view.id),
      line(x, sheetBounds.maxY, x + 1.3, sheetBounds.maxY - 3, "dimension", view.id),
      text(x + 2, (sheetBounds.minY + sheetBounds.maxY) / 2, `${formatted} ${units}`, 3.1, { viewId: view.id }),
    );
  }
  return result;
}

function titleBlockPrimitives(sheet: DrawingSheet, units: BenchProject["units"]) {
  const result: DrawingPrimitive[] = [];
  const margin = 8;
  const width = Math.min(128, sheet.width - margin * 2);
  const x = sheet.width - margin - width;
  const y = sheet.height - margin - 27;
  result.push(
    line(x, y, x + width, y, "title"),
    line(x + width, y, x + width, y + 27, "title"),
    line(x + width, y + 27, x, y + 27, "title"),
    line(x, y + 27, x, y, "title"),
    line(x, y + 12, x + width, y + 12, "title"),
    line(x, y + 19, x + width, y + 19, "title"),
    line(x + width * 0.58, y + 12, x + width * 0.58, y + 27, "title"),
    line(x + width * 0.78, y + 12, x + width * 0.78, y + 27, "title"),
    text(x + 3, y + 5, sheet.titleBlock.title || "UNTITLED DRAWING", 4, { weight: "bold" }),
    text(x + 3, y + 10, sheet.titleBlock.material ? `MATERIAL: ${sheet.titleBlock.material}` : "MATERIAL: -", 2.4),
    text(x + 3, y + 16.5, `DRAWING: ${sheet.titleBlock.drawingNumber || "-"}`, 2.5),
    text(x + width * 0.6, y + 16.5, `REV ${sheet.titleBlock.revision || "-"}`, 2.5),
    text(x + width * 0.8, y + 16.5, `UNITS ${units}`, 2.5),
    text(x + 3, y + 24, `DRAWN BY: ${sheet.titleBlock.drawnBy || "-"}`, 2.4),
    text(x + width * 0.6, y + 24, sheet.titleBlock.date, 2.4),
    text(x + width * 0.8, y + 24, `SHEET ${sheet.name}`, 2.4),
  );
  return result;
}

export function renderDrawingSheet(
  sheet: DrawingSheet,
  bodies: Body[],
  meshes: DrawingMesh[],
  units: BenchProject["units"],
): RenderedDrawingSheet {
  const primitives: DrawingPrimitive[] = [];
  const margin = 8;
  primitives.push(
    line(margin, margin, sheet.width - margin, margin, "border"),
    line(sheet.width - margin, margin, sheet.width - margin, sheet.height - margin, "border"),
    line(sheet.width - margin, sheet.height - margin, margin, sheet.height - margin, "border"),
    line(margin, sheet.height - margin, margin, margin, "border"),
  );
  const viewBounds: Record<string, DrawingBounds> = {};
  const projections = new Map<string, ProjectedDrawingView>();
  sheet.views.forEach((view) => {
    const projection = projectDrawingView(view, bodies, meshes);
    projections.set(view.id, projection);
    const mappedBounds = emptyBounds();
    projection.lines.forEach((segment) => {
      if (segment.hidden && !view.showHiddenLines) return;
      const a = mappedPoint(segment.a, projection, view, units);
      const b = mappedPoint(segment.b, projection, view, units);
      includePoint(mappedBounds, a);
      includePoint(mappedBounds, b);
      primitives.push(line(a[0], a[1], b[0], b[1], segment.hidden ? "hidden" : "visible", view.id));
    });
    projection.sectionLines.forEach((segment) => {
      const a = mappedPoint(segment.a, projection, view, units);
      const b = mappedPoint(segment.b, projection, view, units);
      includePoint(mappedBounds, a);
      includePoint(mappedBounds, b);
      primitives.push(line(a[0], a[1], b[0], b[1], "section", view.id));
    });
    const safeBounds = normalizedBounds(mappedBounds);
    viewBounds[view.id] = safeBounds;
    if (view.type === "section" && projection.sectionLines.length) {
      const spacing = 4;
      const span = safeBounds.maxY - safeBounds.minY;
      for (let x = safeBounds.minX - span; x < safeBounds.maxX; x += spacing)
        primitives.push(line(x, safeBounds.maxY, x + span, safeBounds.minY, "hatch", view.id));
    }
    primitives.push(
      text(view.x, safeBounds.maxY + 6, `${view.name.toUpperCase()} · ${view.type === "section" ? "SECTION" : view.orientation.toUpperCase()} · SCALE ${view.scale}:1`, 2.8, {
        align: "middle",
        weight: "bold",
        viewId: view.id,
      }),
    );
  });
  sheet.dimensions.forEach((dimension) => {
    const view = sheet.views.find((candidate) => candidate.id === dimension.viewId);
    const projection = projections.get(dimension.viewId);
    const bounds = viewBounds[dimension.viewId];
    if (view && projection && bounds)
      primitives.push(...dimensionPrimitives(dimension, view, projection, bounds, units));
  });
  sheet.notes.forEach((note) =>
    primitives.push(...note.text.split("\n").map((lineText, index) =>
      text(note.x, note.y + index * (note.fontSize + 1), lineText, note.fontSize),
    )),
  );
  primitives.push(...titleBlockPrimitives(sheet, units));
  return { width: sheet.width, height: sheet.height, primitives, viewBounds };
}

const xmlEscape = (value: string) => value
  .replaceAll("&", "&amp;")
  .replaceAll("<", "&lt;")
  .replaceAll(">", "&gt;")
  .replaceAll('"', "&quot;");

const lineStyle = (style: DrawingLineStyle) => {
  if (style === "hidden") return 'stroke="#6f7780" stroke-width="0.25" stroke-dasharray="2 1.2"';
  if (style === "section") return 'stroke="#0b1115" stroke-width="0.7"';
  if (style === "hatch") return 'stroke="#737b82" stroke-width="0.18"';
  if (style === "dimension") return 'stroke="#1f5570" stroke-width="0.25"';
  if (style === "border" || style === "title") return 'stroke="#0b1115" stroke-width="0.35"';
  return 'stroke="#0b1115" stroke-width="0.35"';
};

export function drawingSheetToSvg(
  sheet: DrawingSheet,
  bodies: Body[],
  meshes: DrawingMesh[],
  units: BenchProject["units"],
) {
  const rendered = renderDrawingSheet(sheet, bodies, meshes, units);
  const content = rendered.primitives.map((primitive) => {
    if (primitive.kind === "line")
      return `<line x1="${primitive.x1.toFixed(3)}" y1="${primitive.y1.toFixed(3)}" x2="${primitive.x2.toFixed(3)}" y2="${primitive.y2.toFixed(3)}" ${lineStyle(primitive.style)} fill="none" />`;
    return `<text x="${primitive.x.toFixed(3)}" y="${primitive.y.toFixed(3)}" font-family="Arial, sans-serif" font-size="${primitive.size}" font-weight="${primitive.weight === "bold" ? "700" : "400"}" text-anchor="${primitive.align ?? "start"}" fill="#0b1115">${xmlEscape(primitive.text)}</text>`;
  }).join("\n");
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${rendered.width}mm" height="${rendered.height}mm" viewBox="0 0 ${rendered.width} ${rendered.height}"><rect width="100%" height="100%" fill="white"/>${content}</svg>`;
}

function pdfEscape(value: string) {
  return value
    .replaceAll("\\", "\\\\")
    .replaceAll("(", "\\(")
    .replaceAll(")", "\\)")
    .replaceAll("±", "+/-")
    .replaceAll("Ø", "DIA ")
    .replace(/[^\x20-\x7e]/g, "?");
}

function pdfContent(rendered: RenderedDrawingSheet) {
  const points = 72 / 25.4;
  const commands: string[] = ["1 J 1 j"];
  rendered.primitives.forEach((primitive) => {
    if (primitive.kind === "line") {
      const widths: Record<DrawingLineStyle, number> = {
        visible: 0.35, hidden: 0.25, section: 0.7, hatch: 0.18,
        dimension: 0.25, border: 0.35, title: 0.35,
      };
      commands.push(`${(widths[primitive.style] * points).toFixed(3)} w`);
      commands.push(primitive.style === "hidden" ? "[5 3] 0 d" : "[] 0 d");
      const color = primitive.style === "dimension" ? "0.12 0.33 0.44 RG" : "0.04 0.07 0.09 RG";
      commands.push(color);
      commands.push(`${(primitive.x1 * points).toFixed(3)} ${((rendered.height - primitive.y1) * points).toFixed(3)} m ${(primitive.x2 * points).toFixed(3)} ${((rendered.height - primitive.y2) * points).toFixed(3)} l S`);
    } else {
      const x = primitive.x * points;
      const y = (rendered.height - primitive.y) * points;
      const size = primitive.size * points;
      const approximateWidth = pdfEscape(primitive.text).length * size * 0.48;
      const adjustedX = primitive.align === "middle" ? x - approximateWidth / 2 : primitive.align === "end" ? x - approximateWidth : x;
      commands.push(`BT /F1 ${size.toFixed(3)} Tf 0.04 0.07 0.09 rg ${adjustedX.toFixed(3)} ${y.toFixed(3)} Td (${pdfEscape(primitive.text)}) Tj ET`);
    }
  });
  return commands.join("\n");
}

function byteLength(value: string) {
  return new TextEncoder().encode(value).byteLength;
}

export function drawingSheetsToPdf(
  sheets: DrawingSheet[],
  bodies: Body[],
  meshes: DrawingMesh[],
  units: BenchProject["units"],
) {
  const rendered = sheets.map((sheet) => renderDrawingSheet(sheet, bodies, meshes, units));
  const pageCount = rendered.length;
  const fontId = 3 + pageCount * 2;
  const objects: string[] = [];
  objects[1] = "<< /Type /Catalog /Pages 2 0 R >>";
  const pageIds = rendered.map((_, index) => 3 + index * 2);
  objects[2] = `<< /Type /Pages /Kids [${pageIds.map((id) => `${id} 0 R`).join(" ")}] /Count ${pageCount} >>`;
  rendered.forEach((page, index) => {
    const pageId = pageIds[index];
    const contentId = pageId + 1;
    const width = (page.width * 72) / 25.4;
    const height = (page.height * 72) / 25.4;
    const content = pdfContent(page);
    objects[pageId] = `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${width.toFixed(3)} ${height.toFixed(3)}] /Resources << /Font << /F1 ${fontId} 0 R >> >> /Contents ${contentId} 0 R >>`;
    objects[contentId] = `<< /Length ${byteLength(content)} >>\nstream\n${content}\nendstream`;
  });
  objects[fontId] = "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>";
  let pdf = "%PDF-1.4\n%BENCHCAD\n";
  const offsets = [0];
  for (let id = 1; id <= fontId; id += 1) {
    offsets[id] = byteLength(pdf);
    pdf += `${id} 0 obj\n${objects[id]}\nendobj\n`;
  }
  const xref = byteLength(pdf);
  pdf += `xref\n0 ${fontId + 1}\n0000000000 65535 f \n`;
  for (let id = 1; id <= fontId; id += 1)
    pdf += `${String(offsets[id]).padStart(10, "0")} 00000 n \n`;
  pdf += `trailer\n<< /Size ${fontId + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
  return new TextEncoder().encode(pdf);
}

export function resizeDrawingSheet(
  sheet: DrawingSheet,
  size: DrawingSheet["size"],
  orientation: DrawingSheet["orientation"],
) {
  const [width, height] = drawingSheetDimensions(size, orientation);
  return { ...sheet, size, orientation, width, height, updatedAt: new Date().toISOString() };
}
